def _verify_genie_salesforce_search(result: dict[str, Any], sobject: str, return_key: str) -> dict[str, Any]:
    replay = _verify_replay_recipe(result)
    checks = list(replay.get("checks") or [])
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    tool_calls = result.get("tool_calls") or []
    search_call = _find_call(tool_calls, "salesforce.search_records")
    return_call = _find_call(tool_calls, "workato_genie.workflow_return_result")
    search_args = (search_call or {}).get("args") or {}
    search_result = (search_call or {}).get("result") or {}
    return_result = (return_call or {}).get("result") or {}
    filters = search_args.get("filters") if isinstance(search_args.get("filters"), list) else []
    records = search_result.get("records") if isinstance(search_result.get("records"), list) else []
    returned = ((return_result.get("result") or {}).get(return_key) or [])
    if not isinstance(returned, list):
        returned = []
    expected_count = expect.get("expected_record_count")
    expected_filters = expect.get("expected_filters") if isinstance(expect.get("expected_filters"), list) else []
    expected_records = expect.get("expected_records") if isinstance(expect.get("expected_records"), list) else []
    expected_return_records = (
        expect.get("expected_return_records")
        if isinstance(expect.get("expected_return_records"), list)
        else []
    )
    checks.extend([
        _check(
            "recipe_searched_expected_salesforce_object",
            bool(search_call and _ok(search_call) and search_args.get("sobject") == sobject),
            {"expected_sobject": sobject, "search_call": search_call},
        ),
        _check(
            "salesforce_search_count_matches_expected",
            search_result.get("count") == expected_count,
            {"expected_record_count": expected_count, "search_result": search_result},
        ),
        _check(
            "salesforce_search_filters_include_expected",
            all(
                isinstance(expected, dict)
                and any(_contains_subset(actual, expected) for actual in filters if isinstance(actual, dict))
                for expected in expected_filters
            ),
            {"expected_filters": expected_filters, "actual_filters": filters},
        ),
        _check(
            "salesforce_search_records_include_expected",
            all(
                isinstance(expected, dict)
                and any(_contains_subset(record, expected) for record in records if isinstance(record, dict))
                for expected in expected_records
            ),
            {"expected_records": expected_records, "records": records},
        ),
        _check(
            "genie_returned_expected_list_size",
            bool(return_call and _ok(return_call) and len(returned) == expected_count),
            {"return_key": return_key, "returned": returned, "return_call": return_call},
        ),
        _check(
            "genie_returned_expected_records",
            all(
                isinstance(expected, dict)
                and any(_contains_subset(row, expected) for row in returned if isinstance(row, dict))
                for expected in expected_return_records
            ),
            {"expected_return_records": expected_return_records, "returned": returned},
        ),
        _check(
            "live_salesforce_seed_records_cleaned_up",
            bool((details.get("cleanup_response") or {}).get("ok") and not (details.get("cleanup_response") or {}).get("leftovers")),
            {"cleanup_response": details.get("cleanup_response")},
        ),
    ])
    return {"ok": _checks_ok(checks), "checks": checks}


