def verify_62905310(result: dict[str, Any]) -> dict[str, Any]:
    verdict = _verify_replay_recipe(result)
    details = result.get("details") or {}
    id_map = details.get("user_id_map") if isinstance(details.get("user_id_map"), dict) else {}
    if not id_map:
        return verdict
    # Foreign-ID translation exception (benmark_rules): the verification
    # artifact must itself assert the read-back — every create whose args
    # carried a mapped foreign OwnerId must read back with the mapped live
    # target, and the raw literal must appear on no live record. Fail-closed:
    # a declared map with no attestable create fails.
    snapshot = (details.get("final_snapshot") or {}).get("salesforce") or {}
    by_id = {
        str(record.get("id")): (record.get("fields") or {})
        for record in snapshot.get("records") or []
        if isinstance(record, dict)
    }
    attested: list[dict[str, str]] = []
    mismatches: list[dict[str, str]] = []
    for call in result.get("tool_calls") or []:
        args_fields = ((call.get("args") or {}).get("fields")
                       if isinstance(call.get("args"), dict) else None) or {}
        foreign = str(args_fields.get("OwnerId") or "")
        if foreign not in id_map:
            continue
        created_id = str((call.get("result") or {}).get("id") or "")
        live_owner = str((by_id.get(created_id) or {}).get("OwnerId") or "")
        row = {"record": created_id, "foreign": foreign, "live_owner": live_owner}
        (attested if live_owner == str(id_map[foreign]) else mismatches).append(row)
    leaked = sorted(
        record_id for record_id, fields in by_id.items()
        if str(fields.get("OwnerId") or "") in id_map
    )
    checks = list(verdict.get("checks") or [])
    checks.append(_check(
        "mapped_owner_read_back_attested",
        bool(attested) and not mismatches and not leaked,
        {"attested": attested, "mismatches": mismatches,
         "foreign_owner_leaks": leaked, "user_id_map": dict(id_map)},
    ))
    verdict["checks"] = checks
    verdict["ok"] = bool(verdict.get("ok")) and bool(attested) and not mismatches and not leaked
    return verdict


