def verify_130359645(result: dict[str, Any]) -> dict[str, Any]:
    base = _verify_workato_db_final_table(result)
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    expected_channel = str(details.get("expected_channel") or "")
    slack_call = _find_call(result.get("tool_calls") or [], "slack.post_message")
    actual_args = (slack_call or {}).get("args") or {}
    checks = list(base.get("checks") or [])
    # Branch-aware: only require the Slack post (and its override channel) when
    # this variant's expect declares one. Variants covering a no-post branch
    # (e.g. zero stale rows / no matching channel) instead assert that no Slack
    # post was made, consistent with their expect. Posting variants are
    # unaffected because their expect.tools include slack.post_message.
    if "slack.post_message" in (expect.get("tools") or []):
        checks.append(_check(
            "slack_post_used_expected_override_channel",
            bool(slack_call and expected_channel and actual_args.get("channel") == expected_channel),
            {"expected_channel": expected_channel, "actual_args": actual_args},
        ))
    else:
        checks.append(_check(
            "slack_post_absent_as_expected",
            slack_call is None,
            {"slack_call_args": actual_args},
        ))
    return {"ok": _checks_ok(checks), "checks": checks}


