    upsert_args = upsert_call.get("args") if isinstance(upsert_call.get("args"), dict) else {}
    fields = upsert_args.get("fields") if isinstance(upsert_args.get("fields"), dict) else {}
    returned_call = tool_calls[2] if len(tool_calls) > 2 else {}
