    # still equal the seeded value captured in the initial snapshot.
    stage_expected = parameters.get("stage") not in (None, "")
    updated_fields = update_result.get("updated_fields") if isinstance(update_result.get("updated_fields"), dict) else {}
    initial_record = _snapshot_record(details.get("initial_snapshot") or {}, "Opportunity", opportunity_id)
