def verify_129809019(result: dict[str, Any]) -> dict[str, Any]:
    strict = _verify_strict_recipe(result)
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    tool_calls = result.get("tool_calls") or []
    trigger = details.get("trigger") if isinstance(details.get("trigger"), dict) else {}
    parameters = trigger.get("parameters") if isinstance(trigger.get("parameters"), dict) else {}
    expected_account_id = str(parameters.get("account_id") or "")
    search_call = _find_call(tool_calls, "salesforce.search_records") or {}
    search_result = search_call.get("result") if isinstance(search_call.get("result"), dict) else {}
    search_records = search_result.get("records") if isinstance(search_result, dict) else []
    create_call = _find_call(tool_calls, "salesforce.create_record") or {}
    create_result = create_call.get("result") if isinstance(create_call.get("result"), dict) else {}
    contact_id = str(create_result.get("id") or "")
    return_call = _find_call(tool_calls, "workato_genie.workflow_return_result") or {}
    returned_result = return_call.get("result") if isinstance(return_call.get("result"), dict) else {}
    returned = returned_result.get("result") if isinstance(returned_result.get("result"), dict) else {}
    base_url = str((details.get("account_properties") or {}).get("Salesforce.base.url") or "")
    expected_url = f"{base_url}/lightning/r/Contact/{contact_id}/view" if base_url and contact_id else ""
    checks = list(strict.get("checks") or [])
    # Branch-aware: the create-Contact success checks apply only when this
    # variant's expect drives the happy path (account found -> create Contact).
    # A variant covering the account-not-found stop branch (search returns 0 and
    # the recipe stops before create) instead asserts that no Contact was
    # created; the base strict verifier already validates the executed tool
    # sequence for that branch. Success variants are unaffected because their
    # expect.tools include salesforce.create_record.
    expected_tools = expect.get("tools") or []
    if "salesforce.create_record" in expected_tools:
        # The Account lookup is conditional on an optional public input, and a
        # non-invalid-ID lookup error is deliberately swallowed by the raw
        # recipe before Contact creation continues.  Only assert the lookup's
        # result for variants whose expected observable trace actually includes
        # a successful search call.
        if "salesforce.search_records" in expected_tools:
            checks.append(_check(
                "salesforce_search_returned_seeded_account",
                bool(
                    expected_account_id
                    and isinstance(search_records, list)
                    and len(search_records) == 1
                    and str((search_records[0] or {}).get("Id") or (search_records[0] or {}).get("id") or "") == expected_account_id
                ),
                {"expected_account_id": expected_account_id, "search_records": search_records},
            ))
        checks.append(_check(
            "salesforce_created_contact",
            bool(contact_id and create_result.get("sobject") == "Contact"),
            {"create_result": create_result},
        ))
        checks.append(_check(
            "genie_returned_created_contact_id",
            bool(contact_id and str(returned.get("contact_id") or "") == contact_id),
            {"expected_contact_id": contact_id, "returned": returned},
        ))
        checks.append(_check(
            "genie_returned_created_contact_url",
            bool(expected_url and str(returned.get("contact_url") or "") == expected_url),
            {"expected_contact_url": expected_url, "returned": returned},
        ))
    else:
        checks.append(_check(
            "no_contact_created_on_stop_branch",
            contact_id == "",
            {"create_result": create_result, "search_records": search_records},
        ))
    if expect.get("stopped") is True:
        checks.extend(_genie_invalid_id_catch_checks(result))
    return {"ok": _checks_ok(checks), "checks": checks}


