def _verify_snowflake_catch_stop(
    result: dict[str, Any], *, catch_as: str, stop_as: str
) -> dict[str, Any]:
    # Branch-aware wrapper for the sobject_deleted -> TRY -> snowflake
    # upsert (81bd3b4d) -> CATCH -> STOP mirror family. Expect-gated:
    # variants without expect.stopped keep the exact _verify_replay_recipe
    # behavior (existing artifacts byte-unaffected). A stopped:true variant
    # (sanctioned fault injection on 81bd3b4d) additionally pins the catch
    # arm's full observable behavior.
    replay = _verify_replay_recipe(result)
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    if expect.get("stopped") is not True:
        return replay
    raw_execution = details.get("raw_execution") or {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    checks = list(replay.get("checks") or [])
    stop_rows = [row for row in trace if isinstance(row, dict) and row.get("stopped") is True]
    checks.append(_check(
        "catch_stop_is_final_trace_row",
        len(stop_rows) == 1
        and bool(trace)
        and trace[-1] is stop_rows[0]
        and str(stop_rows[0].get("as") or "") == stop_as
        and str(stop_rows[0].get("number")) == str(expect.get("stop_step_number")),
        {
            "reason": "the forced 81bd3b4d upsert failure must divert to the catch and "
                      "end at the stop_with_error step #5 (trace stop rows carry no "
                      "stop_reason; the reason pill is pinned via the catch payload)",
            "expected_stop": {"as": stop_as, "number": expect.get("stop_step_number")},
            "stop_rows": stop_rows,
        },
    ))
    catch_payload = (raw_execution.get("step_outputs") or {}).get(catch_as)
    checks.append(_check(
        "catch_payload_matches_exactly",
        catch_payload == expect.get("catch"),
        {
            "reason": "STOP #5's stop_reason interpolates '#{catch.message}': the "
                      "engine-canonical payload {type: RawRecipeExecutionError, "
                      "message: <forced error>} is pinned exactly",
            "expected_catch": expect.get("catch"),
            "actual_catch": catch_payload,
        },
    ))
    checks.append(_check(
        "no_snowflake_tool_calls_on_catch_branch",
        not [
            call for call in result.get("tool_calls") or []
            if str(call.get("tool") or "").startswith("snowflake.")
        ],
        {"tool_calls": result.get("tool_calls") or []},
    ))
    unchanged_table = str(expect.get("snowflake_unchanged_table") or "")
    initial_tables = ((details.get("initial_snapshot") or {}).get("snowflake") or {}).get("tables") or {}
    final_tables = ((details.get("final_snapshot") or {}).get("snowflake") or {}).get("tables") or {}
    checks.append(_check(
        "snowflake_table_unchanged_on_catch_branch",
        bool(unchanged_table)
        and isinstance(initial_tables.get(unchanged_table), list)
        and initial_tables.get(unchanged_table) == final_tables.get(unchanged_table),
        {
            "reason": "the catch suppresses the write: the live-seeded table must be "
                      "byte-identical between the initial and final snapshots",
            "table": unchanged_table,
            "initial_rows": initial_tables.get(unchanged_table),
            "final_rows": final_tables.get(unchanged_table),
        },
    ))
    checks.append(_check(
        "stopped_run_has_no_return_value",
        raw_execution.get("return_value") is None,
        {"return_value": raw_execution.get("return_value")},
    ))
    return {"ok": _checks_ok(checks), "checks": checks}


