def verify_130744193(result: dict[str, Any]) -> dict[str, Any]:
    strict = _verify_strict_recipe(result)
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    tool_calls = result.get("tool_calls") or []
    search_result = (tool_calls[0] if tool_calls else {}).get("result") or {}
    search_records = search_result.get("records") if isinstance(search_result, dict) else []
    first_record = search_records[0] if isinstance(search_records, list) and search_records else {}
    returned_result = (tool_calls[1] if len(tool_calls) > 1 else {}).get("result") or {}
    returned = returned_result.get("result") if isinstance(returned_result.get("result"), dict) else {}
    opportunities = returned.get("opportunities") if isinstance(returned, dict) else []
    first_returned = opportunities[0] if isinstance(opportunities, list) and opportunities else {}
    expected_null_fields = [str(field) for field in expect.get("expected_null_return_fields") or []]
    checks = list(strict.get("checks") or [])
    checks.append(_check(
        "salesforce_search_returned_one_opportunity",
        bool(isinstance(search_records, list) and len(search_records) == 1 and str((first_record or {}).get("Id") or "")),
        {"search_records": search_records},
    ))
    checks.append(_check(
        "genie_returned_presales_opportunity_fields",
        bool(
            isinstance(first_returned, dict)
            and str(first_returned.get("opportunityId") or "") == str((first_record or {}).get("Id") or "")
            and str(first_returned.get("opportunityName") or "") == str((first_record or {}).get("Name") or "")
            and str(first_returned.get("stage") or "") == str((first_record or {}).get("StageName") or "")
            and str(first_returned.get("closeDate") or "") == str((first_record or {}).get("CloseDate") or "")
            and str(first_returned.get("accountId") or "") == str((first_record or {}).get("AccountId") or "")
            and str(first_returned.get("opportunityDescription") or "") == str((first_record or {}).get("Description") or "")
            and str(first_returned.get("currentState") or "") == str((first_record or {}).get("Situation__c") or "")
            and str(first_returned.get("desiredState") or "") == str((first_record or {}).get("Desired_State__c") or "")
        ),
        {"search_record": first_record, "returned_opportunities": opportunities},
    ))
    checks.append(_check(
        "genie_left_unavailable_unselected_fields_null",
        all(first_returned.get(field) is None for field in expected_null_fields),
        {"expected_null_return_fields": expected_null_fields, "returned_opportunity": first_returned},
    ))
    return {"ok": _checks_ok(checks), "checks": checks}


def verify_130842923(result: dict[str, Any]) -> dict[str, Any]:
    strict = _verify_strict_recipe(result)
    final_table = _verify_workato_db_final_table(result)
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    trigger = details.get("trigger") if isinstance(details.get("trigger"), dict) else {}
    parameters = trigger.get("parameters") if isinstance(trigger.get("parameters"), dict) else {}
    expected_status_fragments = [str(fragment) for fragment in expect.get("status_fragments") or []]
    raw_execution = details.get("raw_execution") if isinstance(details.get("raw_execution"), dict) else {}
    returned = raw_execution.get("return_value") if isinstance(raw_execution.get("return_value"), dict) else {}
    status = str(returned.get("status") or "")
    checks = list(strict.get("checks") or [])
    checks.extend(final_table.get("checks") or [])
    if expected_status_fragments:
        checks.append(_check(
            "genie_returned_not_qualified_instruction",
            bool(
                parameters.get("opp_id")
                and parameters.get("opp_name")
                and str(parameters.get("opp_id")) in status
                and str(parameters.get("opp_name")) in status
                and all(fragment in status for fragment in expected_status_fragments)
            ),
            {"status": status, "parameters": parameters, "expected_fragments": expected_status_fragments},
        ))
    else:
        # Catch-branch variants declare no status_fragments in expect; the
        # recipe must therefore return no status string. Branch selection is
        # expect-driven, so a success variant that wrongly returned no status
        # fails the fragment check above instead of slipping into this branch.
        checks.append(_check(
            "catch_branch_returned_no_status",
            not status,
            {"status": status, "returned": returned},
        ))
    return {"ok": _checks_ok(checks), "checks": checks}


