def _verify_replay_recipe(result: dict[str, Any]) -> dict[str, Any]:
    details = result.get("details") or {}
    raw_execution = details.get("raw_execution") or {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    expected_raw_tools = details.get("expected_raw_tools") if isinstance(details.get("expected_raw_tools"), list) else []
    canonical_expected_tools = [
        ACTION_ALIASES.get(str(tool), str(tool))
        for tool in expected_raw_tools
    ]
    actual_trace_tools = [
        row.get("tool")
        for row in trace
        if isinstance(row, dict) and row.get("keyword") == "action" and row.get("tool")
    ]
    checks = [
        _check(
            "raw_recipe_executed_without_harness_error",
            bool(raw_execution and all(not _trace_failed(row) for row in trace if isinstance(row, dict))),
            {"trace": trace},
        ),
        _check(
            "executed_actions_match_trace_length",
            raw_execution.get("executed_action_count") == len(actual_trace_tools),
            {
                "executed_action_count": raw_execution.get("executed_action_count"),
                "trace_tools": actual_trace_tools,
            },
        ),
        _check(
            "trace_tools_are_allowed_by_raw_recipe",
            all(tool in canonical_expected_tools for tool in actual_trace_tools),
            {
                "expected_raw_tools": expected_raw_tools,
                "canonical_expected_tools": canonical_expected_tools,
                "actual_trace_tools": actual_trace_tools,
            },
        ),
    ]
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    if isinstance(expect.get("tools"), list) or isinstance(expect.get("tool_expectations"), list):
        checks.extend(_verify_strict_recipe(result).get("checks") or [])
    else:
        # Strict policy: every variant must carry ground-truth expectations.
        # Without them only the self-consistency checks above would run, which
        # is not a real verification — fail closed instead of passing silently.
        checks.append(_check(
            "expect_block_missing",
            False,
            {
                "reason": "variant has no expect.tools / expect.tool_expectations; "
                          "strict verification requires an explicit expect block",
                "expect": expect,
            },
        ))
    return {
        "ok": all(
            check["ok"] or check.get("diagnostic") is True
            for check in checks
        ),
        "checks": checks,
    }


def _trace_failed(row: dict[str, Any]) -> bool:
    result = row.get("result")
    return isinstance(result, dict) and result.get("ok") is False


def _verify_strict_recipe(result: dict[str, Any]) -> dict[str, Any]:
    details = result.get("details") or {}
    expect = details.get("expect") or {}
    raw_execution = details.get("raw_execution") or {}
    tool_calls = result.get("tool_calls") or []
    if not isinstance(expect.get("tools"), list) and not isinstance(expect.get("tool_expectations"), list):
        # Strict policy: no expect block means nothing can be verified — fail
        # closed instead of degrading to an empty expectation set.
        return {
            "ok": False,
            "checks": [_check(
                "expect_block_missing",
                False,
                {
                    "reason": "variant has no expect.tools / expect.tool_expectations; "
                              "strict verification requires an explicit expect block",
                    "expect": expect if isinstance(expect, dict) else None,
                },
            )],
        }
    expected_tools = expect.get("tools")
    if not isinstance(expected_tools, list):
        expected_tools = [item.get("tool") for item in expect.get("tool_expectations") or [] if isinstance(item, dict)]
    # ``executed_action_count`` is the public benchmark count: it describes
    # model-selectable connector calls and therefore must agree with the
    # published tool sequence. Some imported Workato recipes also execute
    # internal assign/transform actions that are present in the raw trace but
    # are not callable benchmark tools. Corpus fixtures may preserve that
    # separate raw-runtime invariant in ``raw_executed_action_count``.
    expected_count = int(expect.get("executed_action_count") or len(expected_tools))
    expected_raw_count = int(
        expect.get("raw_executed_action_count")
        if isinstance(expect.get("raw_executed_action_count"), int)
        and not isinstance(expect.get("raw_executed_action_count"), bool)
        else expected_count
    )
    checks = [
        _raw_execution_path_check(raw_execution, expected_raw_count),
        _check(
            "tool_sequence_matches_expected",
            [call.get("tool") for call in tool_calls] == expected_tools,
            {"expected_tools": expected_tools, "actual_tools": [call.get("tool") for call in tool_calls]},
        ),
    ]
    for idx, item in enumerate(expect.get("tool_expectations") or []):
        if not isinstance(item, dict):
            checks.append(_check("tool_expectation_is_object", False, {"index": idx, "value": item}))
            continue
        checks.extend(_strict_tool_checks(idx, item, tool_calls, details))
    return {
        "ok": all(
            check["ok"] or check.get("diagnostic") is True
            for check in checks
        ),
        "checks": checks,
    }


def _strict_tool_checks(
    idx: int,
    item: dict[str, Any],
    tool_calls: list[dict[str, Any]],
    details: dict[str, Any],
) -> list[dict[str, Any]]:
    tool = str(item.get("tool") or "")
    call = tool_calls[idx] if idx < len(tool_calls) else None
    args = (call or {}).get("args") or {}
    result = (call or {}).get("result") or {}
    equivalence = item.get("argument_equivalence") or {}
    raw_boolean_paths = (
        equivalence.get("boolean_paths")
        if isinstance(equivalence, dict)
        else None
    )
    boolean_paths = {
        tuple(map(str, path))
        for path in raw_boolean_paths or []
        if isinstance(path, list) and path
    }
    checks = [
        _check(
            f"tool_{idx}_called_expected_tool",
            bool(
                call
                and call.get("tool") == tool
                and _ok(call) is bool(item.get("result_ok", True))
            ),
            {"expected_tool": tool, "actual_call": call},
        )
    ]
    if isinstance(item.get("args_contains"), dict):
        from benchmark.argument_semantics import compare_argument_subset

        # Legacy fixture files preserve Workato editor serialization, while
        # the canonical public connector trace uses one JSON number type.
        # Normalize the private fixture expectation only; an evaluated agent
        # that sends a numeric string still mismatches the integer gold call.
        expected_args = _canonical_fixture_argument_subset(
            tool,
            item["args_contains"],
            boolean_paths=boolean_paths,
        )
        if (
            tool in {"slack.post_message", "slack.post_reply"}
            and item.get("channel") == "override"
        ):
            # Simulator isolation replaces the configured public destination
            # with a safe runtime channel. Destination restoration is scored
            # separately at the task-description outcome boundary.
            expected_args.pop("channel", None)
        argument_comparison = compare_argument_subset(
            tool,
            args,
            expected_args,
            evaluation_time=details.get("evaluation_time"),
            boolean_paths=boolean_paths,
        )
        sql_equivalence = (
            equivalence.get("sql") if isinstance(equivalence, dict) else None
        )
        result_semantics_fields = (
            equivalence.get("result_semantics_fields")
            if isinstance(equivalence, dict)
            else None
        )
        result_semantics_fields = (
            {
                str(field)
                for field in result_semantics_fields
                if str(field)
            }
            if isinstance(result_semantics_fields, list)
            else set()
        )
        sql_evidence_check = None
        if (
            tool in {
                "snowflake.run_custom_sql",
                "snowflake.search_rows_sql",
                "snowflake.search_rows",
            }
            and (
                sql_equivalence in {"result_semantics", "execution_equivalence"}
                or result_semantics_fields
            )
        ):
            sql_evidence_check = _strict_snowflake_result_equivalence_check(
                idx,
                item,
                result,
                details,
            )
            # Result/state equivalence is diagnostic only under the canonical
            # trace policy. It must neither rescue nor veto exact arguments.
            sql_evidence_check["diagnostic"] = True
            checks.append(sql_evidence_check)
        if (
            not argument_comparison["semantic_ok"]
            and tool in {
                "snowflake.run_custom_sql",
                "snowflake.search_rows_sql",
                "snowflake.search_rows",
            }
            and (
                (
                    sql_equivalence in {"result_semantics", "execution_equivalence"}
                    and "sql" in item["args_contains"]
                    and "sql" in args
                )
                or result_semantics_fields
            )
            and "result_count" in item
            and sql_evidence_check is not None
        ):
            ignored_fields = (
                {"sql"}
                if sql_equivalence in {"result_semantics", "execution_equivalence"}
                else set()
            ) | result_semantics_fields
            actual_without_sql = {
                key: value
                for key, value in args.items()
                if key not in ignored_fields
            }
            expected_without_sql = {
                key: value
                for key, value in expected_args.items()
                if key not in ignored_fields
            }
            non_sql_comparison = compare_argument_subset(
                tool,
                actual_without_sql,
                expected_without_sql,
                evaluation_time=details.get("evaluation_time"),
                boolean_paths=boolean_paths,
            )
            semantic_ok = bool(
                non_sql_comparison["semantic_ok"]
                and _strict_result_count_check(idx, item, result)["ok"]
                and sql_evidence_check["ok"]
            )
            argument_comparison = {
                **argument_comparison,
                "semantic_ok": semantic_ok,
                "mode": (
                    f"snowflake_{sql_equivalence or 'result_semantics'}"
                    if semantic_ok
                    else "mismatch"
                ),
            }
        semantic_check = _check(
            f"tool_{idx}_args_contain_expected_fields",
            bool(argument_comparison["semantic_ok"]),
            {
                "expected_subset": expected_args,
                "actual_args": args,
                "comparison_mode": argument_comparison["mode"],
                "raw_canonical_match": argument_comparison["raw_ok"],
            },
        )
        # Keep connector/result semantics for error analysis only. Primary
        # strict correctness is the raw canonical expectation below.
        semantic_check["diagnostic"] = True
        checks.append(semantic_check)
        raw_check = _check(
            f"tool_{idx}_raw_args_contain_expected_fields",
            bool(argument_comparison["raw_ok"]),
            {"expected_subset": expected_args, "actual_args": args},
        )
        checks.append(raw_check)
    fragments = item.get("text_fragments")
    if tool in {"slack.post_message", "slack.post_reply"}:
        text = str(args.get("text") or "")
        if tool == "slack.post_reply" and args.get("delete_original") is True:
            checks.append(_check(
                f"tool_{idx}_deleted_original_message",
                bool(args.get("channel") and args.get("original_ts")),
                {"actual_args": args},
            ))
        else:
            checks.append(_check(
                f"tool_{idx}_posted_expected_text",
                bool(
                    isinstance(fragments, list)
                    and all(_without_anon_tags(fragment) in text for fragment in fragments)
                ),
                {"expected_fragments": fragments, "actual_text": text},
            ))
    if tool == "slack_bot.generate_menu_options":
        checks.append(_check(
            f"tool_{idx}_returned_expected_options",
            result.get("options") == args.get("options"),
            {"actual_args": args, "actual_result": result},
        ))
        if isinstance(item.get("options_contains"), list):
            checks.append(_check(
                f"tool_{idx}_options_contain_expected_items",
                _contains_subset(result.get("options"), item["options_contains"]),
                {"expected_subset": item["options_contains"], "actual_options": result.get("options")},
            ))
    if item.get("channel") == "override":
        checks.append(_check(
            f"tool_{idx}_used_override_channel",
            bool(args.get("channel")),
            {"actual_args": args},
        ))
    if tool in {"workato_db_table.add_record", "workato_db_table.update_record", "workato_db_table.upsert_record"}:
        checks.extend(_strict_workato_db_write_checks(idx, item, args, result, details))
    if tool in {"lookup_table.add_entry", "lookup_table.update_entry"}:
        checks.extend(_strict_lookup_write_checks(idx, item, args, result, details))
    if tool == "snowflake.upsert_rows_batch":
        checks.extend(_strict_snowflake_upsert_checks(idx, item, args, result, details))
    if tool == "snowflake.update_rows":
        checks.extend(_strict_snowflake_update_checks(idx, item, args, result, details))
    if tool == "salesforce.update_record":
        checks.extend(_strict_salesforce_update_checks(idx, item, args, result, details))
    if "result_count" in item:
        checks.append(_strict_result_count_check(idx, item, result))
    if tool == "workato_api_platform.return_response":
        checks.append(_check(
            f"tool_{idx}_returned_expected_response",
            result.get("response") == args.get("response"),
            {"actual_args": args, "actual_result": result},
        ))
        if "http_status_code" in item:
            checks.append(_check(
                f"tool_{idx}_returned_expected_http_status",
                str(result.get("http_status_code") or "") == str(item.get("http_status_code") or ""),
                {"expected_http_status_code": item.get("http_status_code"), "actual_result": result},
            ))
        if isinstance(item.get("response_contains"), dict):
            from benchmark.argument_semantics import response_contains

            checks.append(_check(
                f"tool_{idx}_response_contains_expected_fields",
                response_contains(
                    "workato_api_platform.return_response",
                    result.get("response"),
                    item["response_contains"],
                    boolean_paths={
                        path[1:]
                        for path in boolean_paths
                        if path and path[0] == "response"
                    },
                ),
                {"expected_subset": item["response_contains"], "actual_response": result.get("response")},
            ))
    if tool in {"workato_recipe_function.return_result", "workato_genie.workflow_return_result"}:
        checks.append(_check(
            f"tool_{idx}_returned_expected_result",
            result.get("result") == args.get("result"),
            {"actual_args": args, "actual_result": result},
        ))
        if isinstance(item.get("result_contains"), dict):
            checks.append(_check(
                f"tool_{idx}_result_contains_expected_fields",
                _contains_subset(result.get("result"), item["result_contains"]),
                {"expected_subset": item["result_contains"], "actual_result": result.get("result")},
            ))
    return checks


def _canonical_fixture_argument_subset(
    tool: str,
    expected: dict[str, Any],
    *,
    boolean_paths: set[tuple[str, ...]],
) -> dict[str, Any]:
    """Migrate legacy fixture pins to the public connector representation.

    Dataset expectations predate the canonical raw-executor boundary.  This
    projection changes only schema-declared scalar encodings and documented
    authoring/runtime fields; it does not add fields, widen subset matching,
    or apply semantic result equivalence.
    """

    result = deepcopy(expected)

    def convert_boolean(path: tuple[str, ...]) -> None:
        parent: Any = result
        for part in path[:-1]:
            if not isinstance(parent, dict) or part not in parent:
                return
            parent = parent[part]
        if not isinstance(parent, dict) or not path or path[-1] not in parent:
            return
        value = parent[path[-1]]
        if isinstance(value, str) and value.strip().casefold() in {"true", "false"}:
            parent[path[-1]] = value.strip().casefold() == "true"

    # Structural return payloads are recipe-authored JSON with no fixed field
    # schema. A string "true" there is exact data, not a connector boolean.
    if tool not in {
        "workato_recipe_function.return_result",
        "workato_genie.workflow_return_result",
    }:
        for path in boolean_paths:
            convert_boolean(path)

    numeric_fields: tuple[str, ...] = ()
    if tool in {
        "salesforce.search_records",
        "snowflake.search_rows",
        "snowflake.search_rows_sql",
    }:
        numeric_fields = ("limit", "offset")
    elif tool == "google_sheets.search_spreadsheet_rows_v4_new":
        numeric_fields = ("count",)
    for field in numeric_fields:
        value = result.get(field)
        if isinstance(value, str) and value.strip().isdigit():
            result[field] = int(value)

    if tool in {"workato_service.call_service", "workato_service.call_service_async"}:
        # ``reply`` is hidden simulator result seeding, never call input.
        result.pop("reply", None)

    if tool == "workato_db_table.get_records":
        if (
            result.get("limit") in {"100", 100}
            and result.get("order_by_field_id") in {None, ""}
        ):
            result.pop("limit", None)
        if result.get("order_by_field_id") in {None, ""}:
            result.pop("order_direction", None)

    return result


def _expected_boolean_paths(
    expect: dict[str, Any],
    tool: str,
) -> set[tuple[str, ...]]:
    """Return schema-backed scalar equivalences declared by hidden gold."""

    paths: set[tuple[str, ...]] = set()
    for item in expect.get("tool_expectations") or []:
        if not isinstance(item, dict) or item.get("tool") != tool:
            continue
        equivalence = item.get("argument_equivalence") or {}
        if not isinstance(equivalence, dict):
            continue
        paths.update(
            tuple(map(str, path))
            for path in equivalence.get("boolean_paths") or []
            if isinstance(path, list) and path
        )
    return paths


def _strict_snowflake_result_equivalence_check(
    idx: int,
    item: dict[str, Any],
    result: dict[str, Any],
    details: dict[str, Any],
) -> dict[str, Any]:
    """Validate the hidden semantic witness for a non-canonical Snowflake SQL.

    Merely declaring an equivalence class is insufficient: the runtime result
    (for reads) or the post-run table state (for writes) must match a hidden
    expectation.  This keeps SQL syntax out of the task description without
    weakening argument correctness to a result-count-only check.
    """

    equivalence = item.get("argument_equivalence") or {}
    mode = equivalence.get("sql") if isinstance(equivalence, dict) else None
    if mode is None and isinstance(
        equivalence.get("result_semantics_fields"), list
    ):
        mode = "result_semantics"
    name = f"tool_{idx}_snowflake_sql_{mode}_matches"
    if mode == "result_semantics":
        expected_rows = item.get("result_rows_contains")
        pointer = str(equivalence.get("evidence_pointer") or "")
        if expected_rows is None and pointer.startswith("expect."):
            expected_rows = details.get("expect") or {}
            for part in pointer.removeprefix("expect.").split("."):
                if not part:
                    continue
                if not isinstance(expected_rows, dict) or part not in expected_rows:
                    expected_rows = None
                    break
                expected_rows = expected_rows[part]
        actual_rows = result.get("records")
        if not isinstance(actual_rows, list):
            actual_rows = result.get("rows")
        ok = isinstance(expected_rows, list) and isinstance(actual_rows, list)
        remaining = list(actual_rows or [])
        if ok and len(remaining) == len(expected_rows):
            for expected in expected_rows:
                if not isinstance(expected, dict):
                    ok = False
                    break
                matches = [
                    row
                    for row in remaining
                    if isinstance(row, dict) and _contains_subset(row, expected)
                ]
                if not matches:
                    ok = False
                    break
                remaining.remove(matches[0])
            ok = bool(ok and not remaining)
        else:
            ok = False
        return _check(
            name,
            bool(ok),
            {
                "reason": "result_semantics requires the returned row multiset "
                "to match the hidden semantic row witness",
                "evidence_pointer": pointer,
                "expected_rows_contains": expected_rows,
                "actual_rows": actual_rows,
            },
        )

    if mode != "execution_equivalence":
        return _check(
            name,
            False,
            {"reason": "unsupported Snowflake SQL equivalence mode", "mode": mode},
        )

    pointer = str(equivalence.get("evidence_pointer") or "")
    pointer_ok = pointer.startswith("expect.")
    expected_rows: Any = details.get("expect") or {}
    if pointer_ok:
        for part in pointer.removeprefix("expect.").split("."):
            if not part:
                continue
            if not isinstance(expected_rows, dict) or part not in expected_rows:
                pointer_ok = False
                break
            expected_rows = expected_rows[part]

    projection = equivalence.get("final_state")
    if projection is None:
        projection = (details.get("expect") or {}).get(
            "sql_execution_equivalence"
        )
    projection_ok = isinstance(projection, dict)
    table = str((projection or {}).get("table") or "")
    row_key = str((projection or {}).get("row_key") or "")
    suffix_expected_field = str(
        (projection or {}).get("suffix_expected_field") or ""
    )
    suffix_actual_field = str(
        (projection or {}).get("suffix_actual_field") or ""
    )
    actual_rows = (
        ((details.get("final_snapshot") or {}).get("snowflake") or {})
        .get("tables", {})
        .get(table)
    )
    ok = bool(
        pointer_ok
        and projection_ok
        and table
        and row_key
        and isinstance(expected_rows, list)
        and isinstance(actual_rows, list)
        and len(expected_rows) == len(actual_rows)
    )
    if ok:
        actual_by_key: dict[str, dict[str, Any]] = {}
        for row in actual_rows:
            if not isinstance(row, dict) or row_key not in row:
                ok = False
                break
            key = str(row.get(row_key))
            if key in actual_by_key:
                ok = False
                break
            actual_by_key[key] = row
        for expected in expected_rows:
            if not ok or not isinstance(expected, dict) or row_key not in expected:
                ok = False
                break
            actual = actual_by_key.get(str(expected.get(row_key)))
            if not isinstance(actual, dict):
                ok = False
                break
            for field, value in expected.items():
                if field == suffix_expected_field:
                    if not suffix_actual_field or not str(
                        actual.get(suffix_actual_field) or ""
                    ).endswith(str(value or "")):
                        ok = False
                        break
                elif actual.get(field) != value:
                    ok = False
                    break

    return _check(
        name,
        bool(ok),
        {
            "reason": "execution_equivalence requires the hidden expected row "
            "multiset to match the declared final Snowflake table projection",
            "evidence_pointer": pointer,
            "final_state_projection": projection,
            "expected_rows": expected_rows,
            "actual_rows": actual_rows,
        },
    )


def _strict_result_count_check(idx: int, item: dict[str, Any], result: dict[str, Any]) -> dict[str, Any]:
    count = next(
        (
            result[key]
            for key in ("count", "list_size", "totalSize")
            if isinstance(result.get(key), int)
            and not isinstance(result.get(key), bool)
        ),
        None,
    )
    if count is None:
        rows = next(
            (
                result[key]
                for key in (
                    "records",
                    "entries",
                    "options",
                    "results",
                    "rows",
                )
                if isinstance(result.get(key), list)
            ),
            None,
        )
        if rows is not None:
            count = len(rows)
    if (
        count is None
        and str(item.get("tool") or "") == "lookup_table.get_entry"
    ):
        count = 1 if isinstance(result.get("entry"), dict) else 0
    if count is None:
        count = 0
    return _check(
        f"tool_{idx}_result_count_matches",
        count == item.get("result_count"),
        {"expected_count": item.get("result_count"), "actual_count": count, "actual_result": result},
    )


def _salesforce_snapshot_record_id(snapshot: Any, sobject: str, name: str) -> str:
    if not isinstance(snapshot, dict):
        return ""
    salesforce = snapshot.get("salesforce")
    records = salesforce.get("records") if isinstance(salesforce, dict) else []
    for row in records or []:
        if not isinstance(row, dict):
            continue
        fields = row.get("fields") if isinstance(row.get("fields"), dict) else {}
        if str(row.get("sobject") or "") == sobject and str(fields.get("Name") or "") == name:
            return str(row.get("id") or fields.get("Id") or "")
    return ""


def _contains_args(actual: Any, expected: Any) -> bool:
    """args_contains comparator. Dicts: every expected key must be present and
    match (extra actual keys allowed — agents may pass benign extras). Lists:
    EXACT length with element-wise comparison — a trailing extra element (e.g.
    a junk search filter) is a mismatch, unlike _contains_subset's prefix
    semantics. Scalars: equality; "__ANY__" wildcard accepted."""
    from benchmark.argument_semantics import raw_contains

    return raw_contains(actual, expected)


def _contains_subset(actual: Any, expected: Any) -> bool:
    if expected == "__ANY__":
        # Explicit any-value assertion for live-assigned identifiers (e.g.
        # Salesforce CaseNumber): the field must be present and non-empty, but
        # its value is assigned by the live system on every run.
        return actual not in (None, "")
    if isinstance(expected, dict):
        if not isinstance(actual, dict):
            return False
        return all(key in actual and _contains_subset(actual[key], value) for key, value in expected.items())
    if isinstance(expected, list):
        if not isinstance(actual, list) or len(actual) < len(expected):
            return False
        return all(_contains_subset(actual[idx], value) for idx, value in enumerate(expected))
    return actual == expected


def _strict_workato_db_write_checks(
    idx: int,
    item: dict[str, Any],
    args: dict[str, Any],
    result: dict[str, Any],
    details: dict[str, Any],
) -> list[dict[str, Any]]:
    def storage_text(value: Any) -> str:
        # WorkatoDbTableMock._clean models the connector boundary: scalar
        # values are stored as text and booleans use JSON-style lowercase.
        # Comparing with plain ``str`` would incorrectly reject a correct
        # ``True`` argument after it round-trips as ``"true"``.
        if isinstance(value, bool):
            return "true" if value else "false"
        return str(value)

    table_id = str(item.get("table_id") or args.get("table_id") or "")
    record = args.get("record") or {}
    final_snapshot = details.get("final_snapshot") or {}
    rows = (
        final_snapshot.get("workato_db_table", {})
        .get("tables", {})
        .get(table_id, [])
    )
    # A None-valued written field never reaches storage: the mock's _clean
    # drops null params, so the previous cell value (if any) survives the
    # write. The final row therefore cannot be constrained by nil-written
    # fields — only non-nil written values must round-trip (stringified).
    # Explicit match_fields pins are honored verbatim (author's choice).
    # Semantics mirror the engine's data-table write boundary (mapped-nil
    # is sent as null in the request, then dropped at storage by _clean).
    match_fields = (
        item.get("match_fields")
        if isinstance(item.get("match_fields"), list)
        else [key for key, value in record.items() if value is not None]
    )
    matching_rows = [
        row for row in rows
        if isinstance(row, dict)
        and all(
            storage_text(row.get(field)) == storage_text(record.get(field))
            for field in match_fields
        )
    ]
    checks = [
        _check(
            f"tool_{idx}_workato_db_final_row_matches",
            bool(matching_rows and all(
                storage_text(matching_rows[0].get(key)) == storage_text(value)
                for key, value in record.items()
                if value is not None
            )),
            {
                "table_id": table_id,
                "record": record,
                "match_fields": match_fields,
                "matching_rows": matching_rows,
                "row_count": len(rows),
            },
        )
    ]
    if "created" in item:
        checks.append(_check(
            f"tool_{idx}_upsert_created_flag_matches",
            result.get("created") is item.get("created"),
            {"expected_created": item.get("created"), "actual_result": result},
        ))
    return checks


def _strict_lookup_write_checks(
    idx: int,
    item: dict[str, Any],
    args: dict[str, Any],
    result: dict[str, Any],
    details: dict[str, Any],
) -> list[dict[str, Any]]:
    table_id = str(item.get("lookup_table_id") or args.get("lookup_table_id") or "")
    record = args.get("parameters") or {}
    final_snapshot = details.get("final_snapshot") or {}
    rows = (
        final_snapshot.get("lookup_table", {})
        .get("tables", {})
        .get(table_id, [])
    )
    entry_id = result.get("id", args.get("id"))
    matching_rows = [
        row for row in rows
        if isinstance(row, dict)
        and (str(row.get("id")) == str(entry_id) or str(row.get("_row_id")) == str(entry_id))
    ]
    checks = [
        _check(
            f"tool_{idx}_lookup_final_entry_matches",
            bool(matching_rows and all(str(matching_rows[0].get(key)) == str(value) for key, value in record.items())),
            {
                "lookup_table_id": table_id,
                "entry_id": entry_id,
                "record": record,
                "matching_rows": matching_rows,
            },
        )
    ]
    return checks


def _strict_snowflake_upsert_checks(
    idx: int,
    item: dict[str, Any],
    args: dict[str, Any],
    result: dict[str, Any],
    details: dict[str, Any],
) -> list[dict[str, Any]]:
    table = str(item.get("table") or args.get("table") or "")
    expected_rows = item.get("rows") if isinstance(item.get("rows"), list) else args.get("rows")
    if not isinstance(expected_rows, list):
        expected_rows = []
    expected_rows = [
        {
            str(key): _canonical_snowflake_fixture_value(value)
            for key, value in row.items()
        }
        if isinstance(row, dict)
        else row
        for row in expected_rows
    ]
    final_snapshot = details.get("final_snapshot") or {}
    snapshot_tables = (
        final_snapshot.get("snowflake", {}).get("tables", {})
    )
    rows = snapshot_tables.get(table, [])
    if not rows and isinstance(snapshot_tables, dict):
        candidates = [
            value
            for name, value in snapshot_tables.items()
            if str(name).casefold() == table.casefold()
            or str(name).casefold().endswith("." + table.casefold())
        ]
        if len(candidates) == 1:
            rows = candidates[0]
    applied_rows = (
        result.get("rows")
        if isinstance(result.get("rows"), list)
        else []
    )
    row_checks: list[dict[str, Any]] = []
    match_fields = item.get("match_fields") if isinstance(item.get("match_fields"), list) else None
    for row_idx, expected in enumerate(expected_rows):
        if not isinstance(expected, dict):
            row_checks.append(_check(
                f"tool_{idx}_snowflake_expected_row_{row_idx}_is_object",
                False,
                {"expected": expected},
            ))
            continue
        actual_applied = (
            applied_rows[row_idx]
            if row_idx < len(applied_rows)
            and isinstance(applied_rows[row_idx], dict)
            else None
        )
        row_checks.append(_check(
            f"tool_{idx}_snowflake_applied_row_{row_idx}_matches",
            bool(
                actual_applied is not None
                and all(
                    str(_case_field(actual_applied, key)) == str(value)
                    for key, value in expected.items()
                )
            ),
            {
                "table": table,
                "expected": expected,
                "actual_applied_row": actual_applied,
                "applied_row_count": len(applied_rows),
            },
        ))

    # A batch may write the same logical key more than once. Connector
    # results preserve every applied row in order, while the final table is
    # last-write-wins. Verify only the final expected value per key against
    # the snapshot instead of incorrectly requiring superseded values there.
    final_expected: dict[tuple[str, ...], dict[str, Any]] = {}
    for expected in expected_rows:
        if not isinstance(expected, dict):
            continue
        fields = match_fields or list(expected.keys())
        key = tuple(str(expected.get(field)) for field in fields)
        final_expected[key] = expected
    for final_idx, expected in enumerate(final_expected.values()):
        fields = match_fields or list(expected.keys())
        matching_rows = [
            row for row in rows
            if isinstance(row, dict)
            and all(str(_case_field(row, field)) == str(expected.get(field)) for field in fields)
        ]
        row_checks.append(_check(
            f"tool_{idx}_snowflake_final_row_{final_idx}_matches",
            bool(matching_rows and all(str(_case_field(matching_rows[0], key)) == str(value) for key, value in expected.items())),
            {
                "table": table,
                "expected": expected,
                "match_fields": fields,
                "matching_rows": matching_rows,
                "row_count": len(rows),
            },
        ))
    checks = [
        _check(
            f"tool_{idx}_snowflake_upsert_count_matches",
            result.get("upserted") == len(expected_rows),
            {"expected_count": len(expected_rows), "actual_result": result},
        )
    ]
    if "created_count" in item:
        checks.append(_check(
            f"tool_{idx}_snowflake_created_count_matches",
            result.get("created") == item.get("created_count"),
            {"expected_created": item.get("created_count"), "actual_result": result},
        ))
    if "updated_count" in item:
        checks.append(_check(
            f"tool_{idx}_snowflake_updated_count_matches",
            result.get("updated") == item.get("updated_count"),
            {"expected_updated": item.get("updated_count"), "actual_result": result},
        ))
    return checks + row_checks


def _canonical_snowflake_fixture_value(value: Any) -> Any:
    """Decode legacy SQL-literal quoting from connector row fixtures."""

    if (
        isinstance(value, str)
        and len(value) >= 2
        and value.startswith("'")
        and value.endswith("'")
    ):
        return value[1:-1].replace("''", "'")
    return value


def _case_field(row: dict[str, Any], field: str) -> Any:
    if field in row:
        return row[field]
    lower = str(field).lower()
    if lower in row:
        return row[lower]
    upper = str(field).upper()
    if upper in row:
        return row[upper]
    for key, value in row.items():
        key_lower = str(key).lower()
        if key_lower == lower or key_lower.startswith(lower + "_"):
            return value
    return None


def _snowflake_row_deleted(rows: list[Any], record_id: str) -> bool:
    for row in rows:
        if not isinstance(row, dict):
            continue
        if str(_case_field(row, "id")) != str(record_id):
            continue
        return _truthy(_case_field(row, "isdeleted"))
    return False


def _snowflake_row_active(rows: list[Any], record_id: str) -> bool:
    for row in rows:
        if not isinstance(row, dict):
            continue
        if str(_case_field(row, "id")) != str(record_id):
            continue
        return not _truthy(_case_field(row, "isdeleted"))
    return False


def _truthy(value: Any) -> bool:
    if isinstance(value, bool):
        return value
    return str(value).strip().lower() in {"true", "1", "yes"}


def _strict_snowflake_update_checks(
    idx: int,
    item: dict[str, Any],
    args: dict[str, Any],
    result: dict[str, Any],
    details: dict[str, Any],
) -> list[dict[str, Any]]:
    table = str(item.get("table") or args.get("table") or "")
    expected_columns = item.get("columns") if isinstance(item.get("columns"), dict) else args.get("columns") or {}
    final_snapshot = details.get("final_snapshot") or {}
    rows = (
        final_snapshot.get("snowflake", {})
        .get("tables", {})
        .get(table, [])
    )
    where_field, where_value = _parse_snowflake_where(str(args.get("where") or ""))
    matching_rows = [
        row for row in rows
        if isinstance(row, dict) and str(_case_field(row, where_field)) == where_value
    ]
    checks = [
        _check(
            f"tool_{idx}_snowflake_updated_count_matches",
            "updated_count" not in item or result.get("updated") == item.get("updated_count"),
            {"expected_updated": item.get("updated_count"), "actual_result": result},
        ),
        _check(
            f"tool_{idx}_snowflake_updated_columns_match",
            bool(
                matching_rows
                and all(str(_case_field(matching_rows[0], key)) == str(value) for key, value in expected_columns.items())
            ),
            {
                "table": table,
                "where": args.get("where"),
                "expected_columns": expected_columns,
                "matching_rows": matching_rows,
                "row_count": len(rows),
            },
        ),
    ]
    return checks


def _strict_salesforce_update_checks(
    idx: int,
    item: dict[str, Any],
    args: dict[str, Any],
    result: dict[str, Any],
    details: dict[str, Any],
) -> list[dict[str, Any]]:
    sobject = str(item.get("sobject") or args.get("sobject") or "")
    records = args.get("records") if isinstance(args.get("records"), list) else None
    update_rows = (
        [row for row in records if isinstance(row, dict)]
        if records is not None
        else [{"sobject": sobject, "id": args.get("id"), "fields": args.get("fields")}]
    )
    final_snapshot = details.get("final_snapshot") or {}
    expected_result_ok = bool(item.get("result_ok", True))
    result_rows = (
        result.get("records")
        if records is not None and isinstance(result.get("records"), list)
        else [result]
    )
    final_rows = []
    for row in update_rows:
        row_sobject = str(row.get("sobject") or sobject)
        record_id = str(row.get("id") or "")
        fields = row.get("fields") if isinstance(row.get("fields"), dict) else {}
        final_record = _snapshot_record(final_snapshot, row_sobject, record_id)
        final_fields = final_record.get("fields") if isinstance(final_record.get("fields"), dict) else {}
        final_rows.append((row_sobject, record_id, fields, final_fields))
    checks = [
        _check(
            f"tool_{idx}_salesforce_update_succeeded",
            result.get("ok") is expected_result_ok
            and bool(update_rows)
            and all(bool(row_sobject) and bool(record_id) for row_sobject, record_id, _, _ in final_rows),
            {"actual_args": args, "actual_result": result},
        ),
        _check(
            f"tool_{idx}_salesforce_final_fields_match_update_args",
            bool(final_rows)
            and len(result_rows) == len(final_rows)
            and all(
                (
                    bool(final_fields)
                    and _contains_salesforce_field_subset(final_fields, fields)
                )
                if (result_row or {}).get("ok") is True
                else not _contains_salesforce_field_subset(final_fields, fields)
                for (_, _, fields, final_fields), result_row
                in zip(final_rows, result_rows)
            ),
            {
                "sobject": sobject,
                "updates": [
                    {
                        "record_id": record_id,
                        "expected_fields": fields,
                        "final_fields": final_fields,
                    }
                    for _, record_id, fields, final_fields in final_rows
                ],
            },
        ),
    ]
    if isinstance(item.get("fields_contains"), dict):
        checks.append(_check(
            f"tool_{idx}_salesforce_update_args_contain_expected_fields",
            bool(final_rows)
            and all(_contains_subset(fields, item["fields_contains"]) for _, _, fields, _ in final_rows),
            {"expected_subset": item["fields_contains"], "actual_updates": update_rows},
        ))
        checks.append(_check(
            f"tool_{idx}_salesforce_final_fields_contain_expected_fields",
            bool(final_rows)
            and all(
                _contains_salesforce_field_subset(final_fields, item["fields_contains"])
                for _, _, _, final_fields in final_rows
            ),
            {"expected_subset": item["fields_contains"], "final_updates": final_rows},
        ))
    return checks


def _same_number(actual: Any, expected: Any) -> bool:
    from decimal import Decimal, InvalidOperation
    if isinstance(actual, bool) or isinstance(expected, bool):
        return False
    if not isinstance(actual, (int, float, str)) or not isinstance(expected, (int, float, str)):
        return False
    try:
        return Decimal(str(actual)) == Decimal(str(expected))
    except (InvalidOperation, ValueError):
        return False


def _contains_salesforce_field_subset(actual: Any, expected: Any) -> bool:
    if not isinstance(actual, dict) or not isinstance(expected, dict):
        return False
    for key, value in expected.items():
        if key not in actual:
            return False
        if value == "" and actual[key] is None:
            continue
        # Salesforce trims trailing whitespace on save; compare accordingly so a
        # recipe-computed "Austin, " matches the stored "Austin,".
        if (
            isinstance(value, str)
            and isinstance(actual[key], str)
            and value != actual[key]
            and value.rstrip() == actual[key].rstrip()
        ):
            continue
        # Numeric equivalence: currency/number fields read back as JSON numbers
        # (73000.0) while recipe args render them as strings ("73000").
        if _same_number(actual[key], value):
            continue
        if not _contains_subset(actual[key], value):
            return False
    return True


def _parse_snowflake_where(where: str) -> tuple[str, str]:
    text = str(where or "").strip()
    if "=" not in text:
        return "", ""
    field, value = text.split("=", 1)
    field = field.strip().strip('"')
    value = value.strip()
    if value.startswith("'") and value.endswith("'"):
        value = value[1:-1].replace("''", "'")
    return field, value


def _verify_slack_post_expect(result: dict[str, Any]) -> dict[str, Any]:
    details = result.get("details") or {}
    expect = details.get("expect") or {}
    if "executed_action_count" not in expect:
        # Strict policy: a missing expect block must not be indistinguishable
        # from a declared zero-post branch — fail closed.
        return {
            "ok": False,
            "checks": [_check(
                "expect_block_missing",
                False,
                {
                    "reason": "variant expect has no executed_action_count; a zero-post "
                              "branch must declare it explicitly",
                    "expect": expect if isinstance(expect, dict) else None,
                },
            )],
        }
    expected_count = int(expect.get("executed_action_count") or 0)
    expected_fragments = expect.get("text_fragments") or []
    expected_channel = details.get("expected_channel")
    raw_execution = details.get("raw_execution") or {}
    tool_calls = result.get("tool_calls") or []
    post_calls = [call for call in tool_calls if call.get("tool") == "slack.post_message"]
    post_call = post_calls[0] if post_calls else None
    args = (post_call or {}).get("args") or {}
    text = str(args.get("text") or "")
    checks = [
        _raw_execution_path_check(raw_execution, expected_count),
        _check(
            "slack_post_count_matches_expected_path",
            len(post_calls) == expected_count,
            {"expected_count": expected_count, "actual_count": len(post_calls), "tool_calls": tool_calls},
        ),
    ]
    if expected_count == 0:
        checks.append(_check(
            "conditional_path_skipped_slack_post",
            post_call is None,
            {"tool_calls": tool_calls},
        ))
        return {"ok": _checks_ok(checks), "checks": checks}

    checks.extend([
        _check(
            "recipe_posted_slack_message",
            bool(post_call and _ok(post_call)),
            {"tool": "slack.post_message", "result": (post_call or {}).get("result")},
        ),
        _check(
            "posted_to_expected_channel",
            bool(args.get("channel") == expected_channel),
            {"expected_channel": expected_channel, "actual_args": args},
        ),
        _check(
            "posted_expected_text_fragments",
            bool(
                isinstance(expected_fragments, list)
                and expected_fragments
                and all(str(fragment) in text for fragment in expected_fragments)
            ),
            {"expected_fragments": expected_fragments, "actual_text": text},
        ),
    ])
    return {"ok": _checks_ok(checks), "checks": checks}


def _verify_delete_original_expect(result: dict[str, Any]) -> dict[str, Any]:
    details = result.get("details") or {}
    expect = details.get("expect") or {}
    if "executed_action_count" not in expect:
        return {
            "ok": False,
            "checks": [_check(
                "expect_block_missing",
                False,
                {"reason": "strict verification requires expect.executed_action_count"},
            )],
        }
    expected_count = int(expect["executed_action_count"])
    seed_message = details.get("seed_message") or {}
    raw_execution = details.get("raw_execution") or {}
    tool_calls = result.get("tool_calls") or []
    harness_calls = (result.get("harness_tool_calls") or []) + (details.get("seed_harness_tool_calls") or [])
    seed_post = _find_call(harness_calls, "harness.slack.seed_message")
    delete_call = _find_call(tool_calls, "slack.post_reply")
    delete_args = (delete_call or {}).get("args") or {}
    checks = [
        _check(
            "seed_posted_target_message",
            bool(seed_post and _ok(seed_post) and seed_message.get("channel") and seed_message.get("ts")),
            {
                "tool": "harness.slack.seed_message",
                "channel": seed_message.get("channel"),
                "ts": seed_message.get("ts"),
            },
        ),
        _check(
            "recipe_deleted_target_message",
            bool(
                delete_call
                and _ok(delete_call)
                and delete_args.get("channel") == seed_message.get("channel")
                and delete_args.get("original_ts") == seed_message.get("ts")
                and delete_args.get("delete_original") is True
            ),
            {
                "tool": "slack.post_reply",
                "expected_channel": seed_message.get("channel"),
                "expected_ts": seed_message.get("ts"),
                "actual_args": delete_args,
                "result": (delete_call or {}).get("result"),
            },
        ),
        _raw_execution_path_check(raw_execution, expected_count),
    ]
    return {"ok": _checks_ok(checks), "checks": checks}


def _find_call(calls: list[dict[str, Any]], tool: str) -> dict[str, Any] | None:
    for call in calls:
        if call.get("tool") == tool:
            return call
    return None


def _snapshot_records(snapshot: dict[str, Any], sobject: str) -> list[dict[str, Any]]:
    records = ((snapshot.get("salesforce") or {}).get("records") or [])
    return [
        record for record in records
        if isinstance(record, dict) and record.get("sobject") == sobject
    ]


def _snapshot_record(snapshot: dict[str, Any], sobject: str, record_id: str) -> dict[str, Any]:
    for record in _snapshot_records(snapshot, sobject):
        fields = record.get("fields") if isinstance(record.get("fields"), dict) else {}
        if str(record.get("id") or fields.get("Id") or "") == str(record_id):
            return record
    return {}


def _ok(call: dict[str, Any]) -> bool:
    return bool((call.get("result") or {}).get("ok"))


def _raw_execution_path_check(raw_execution: dict[str, Any], expected_executed: int) -> dict[str, Any]:
    return _check(
        "raw_recipe_executed_expected_path",
        bool(
            raw_execution
            and raw_execution.get("executed_action_count") == expected_executed
        ),
        {
            "expected_executed_action_count": expected_executed,
            "raw_action_count": raw_execution.get("raw_action_count"),
            "executed_action_count": raw_execution.get("executed_action_count"),
            "trace": raw_execution.get("trace"),
        },
    )


def _check(name: str, ok: bool, details: dict[str, Any]) -> dict[str, Any]:
    return {"name": name, "ok": ok, "details": details}


def _checks_ok(checks: list[dict[str, Any]]) -> bool:
    """Treat canonical-fidelity diagnostics as non-blocking everywhere."""

    return all(
        check.get("ok") is True or check.get("diagnostic") is True
        for check in checks
    )


