def _lookup_rows(snapshot: Any, table_id: str) -> list[dict[str, Any]]:
    if not isinstance(snapshot, dict):
        return []
    tables = ((snapshot.get("lookup_table") or {}).get("tables") or {})
    rows = tables.get(table_id)
    return rows if isinstance(rows, list) else []

def _row_field(row: dict[str, Any], field: str) -> Any:
    if field in row:
        return row[field]
    lower = str(field).lower()
    for key, value in row.items():
        if str(key).lower() == lower:
            return value
    return None

