def verify_89048964(result: dict[str, Any]) -> dict[str, Any]:
    SNOWFLAKE_TABLE = "RPA.QUEUE"
    base = _verify_replay_recipe(result)
    checks = list(base.get("checks") or [])
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    rows = (
        (details.get("final_snapshot") or {})
        .get("snowflake", {})
        .get("tables", {})
        .get(SNOWFLAKE_TABLE, [])
    )
    for idx, expected in enumerate(expect.get("final_rows") or []):
        if not isinstance(expected, dict):
            checks.append(_check(f"final_row_{idx}_is_object", False, {"value": expected}))
            continue
        job_id = str(expected.get("job_id"))
        matching = [
            row for row in rows
            if isinstance(row, dict) and str(_row_field(row, "job_id")) == job_id
        ]
        ok = bool(
            matching
            and all(str(_row_field(matching[0], key)) == str(value) for key, value in expected.items())
        )
        checks.append(_check(
            f"rpa_queue_job_{idx}_final_state_matches",
            ok,
            {
                "table": SNOWFLAKE_TABLE,
                "expected": expected,
                "matching_rows": matching,
                "row_count": len(rows),
            },
        ))
    if "final_row_count" in expect:
        checks.append(_check(
            "rpa_queue_final_row_count_matches",
            len(rows) == expect.get("final_row_count"),
            {"expected": expect.get("final_row_count"), "actual": len(rows), "rows": rows},
        ))
    return {"ok": _checks_ok(checks), "checks": checks}

