def verify_50815491(result: dict[str, Any]) -> dict[str, Any]:
    base = _verify_replay_recipe(result)
    checks = list(base.get("checks") or [])
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") or {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    actual_trace_tools = [
        row.get("tool")
        for row in trace
        if isinstance(row, dict) and row.get("keyword") == "action" and row.get("tool")
    ]
    expected_trace_tools = expect.get("trace_tools")
    if isinstance(expected_trace_tools, list):
        checks.append(_check(
            "raw_trace_tools_match_expected",
            actual_trace_tools == expected_trace_tools,
            {"expected_trace_tools": expected_trace_tools, "actual_trace_tools": actual_trace_tools},
        ))
    else:
        checks.append(_check(
            "expect_trace_tools_missing",
            False,
            {
                "reason": "recipe 50815491 variants must pin expect.trace_tools "
                          "(branch + Workato-runtime step ground truth)",
                "expect": expect,
            },
        ))
    stop_rows = [
        row for row in trace
        if isinstance(row, dict) and row.get("keyword") == "stop" and row.get("stopped")
    ]
    if isinstance(expect.get("graceful_stop"), bool):
        checks.append(_check(
            "graceful_stop_matches_expected",
            bool(stop_rows) == expect["graceful_stop"],
            {"expected_graceful_stop": expect["graceful_stop"], "stop_rows": stop_rows},
        ))
    else:
        checks.append(_check(
            "expect_graceful_stop_missing",
            False,
            {
                "reason": "recipe 50815491 variants must pin expect.graceful_stop "
                          "(the unconditional step-13 stop is part of the ground truth)",
                "expect": expect,
            },
        ))
    checks.append(_check(
        "dead_code_step_14_never_executes",
        all(str(row.get("number")) != "14" for row in trace if isinstance(row, dict) and row.get("keyword") == "action"),
        {"reason": "step 14 parse_json sits after the unconditional stop", "trace_tools": actual_trace_tools},
    ))
    seed_message = details.get("seed_message") if isinstance(details.get("seed_message"), dict) else {}
    post_calls = [
        call for call in result.get("tool_calls") or []
        if call.get("tool") == "slack.post_message"
    ]
    if expect.get("first_post_updates_seed_message"):
        first_args = (post_calls[0].get("args") or {}) if post_calls else {}
        checks.append(_check(
            "first_post_updates_seed_message_ts",
            bool(
                seed_message.get("ts")
                and post_calls
                and str(first_args.get("ts") or "") == str(seed_message.get("ts"))
            ),
            {"seed_message": seed_message, "first_post_args": first_args},
        ))
    if expect.get("catch_post_threads_seed_message"):
        last_args = (post_calls[-1].get("args") or {}) if post_calls else {}
        checks.append(_check(
            "catch_post_threads_under_seed_message_ts",
            bool(
                seed_message.get("ts")
                and post_calls
                and str(last_args.get("thread_ts") or "") == str(seed_message.get("ts"))
            ),
            {"seed_message": seed_message, "last_post_args": last_args},
        ))
    return {"ok": _checks_ok(checks), "checks": checks}


