def verify_90817361(result: dict[str, Any]) -> dict[str, Any]:
    base = _verify_strict_recipe(result)
    checks = list(base.get("checks") or [])
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    tool_calls = result.get("tool_calls") or []

    # First-response pin (Workato first-response-wins; the executor treats
    # return_response as terminal, so exactly one response fires per run).
    responses = [call for call in tool_calls if call.get("tool") == "workato_api_platform.return_response"]
    expected_status = str(expect.get("first_response_status") or "")
    if expected_status not in {"200", "404"}:
        checks.append(_check(
            "expect_first_response_status_missing",
            False,
            {"reason": "recipe 90817361 variants must pin expect.first_response_status", "expect": expect},
        ))
    else:
        first = responses[0] if responses else None
        checks.append(_check(
            "first_return_response_status_matches",
            bool(
                first
                and str((first.get("result") or {}).get("http_status_code") or "") == expected_status
                and (first.get("result") or {}).get("ok") is True
            ),
            {"expected_status": expected_status, "responses": responses},
        ))
        checks.append(_check(
            "return_response_terminates_run",
            len(responses) == 1,
            {"reason": "executor return_response is terminal; exactly one response per run",
             "responses": responses},
        ))

    # Zero-row update pin for the NETSUITE cross-reference bug path: the update
    # where renders job_id = '' (QUEUE current_item is missing), so the live
    # update must touch 0 rows while carrying the recipe's exact columns.
    zero_row_updates = expect.get("zero_row_updates")
    if isinstance(zero_row_updates, list):
        for item in zero_row_updates:
            if not isinstance(item, dict):
                checks.append(_check("zero_row_update_item_is_object", False, {"item": item}))
                continue
            idx = int(item.get("call_index", -1))
            call = tool_calls[idx] if 0 <= idx < len(tool_calls) else None
            args = (call or {}).get("args") or {}
            call_result = (call or {}).get("result") or {}
            checks.append(_check(
                f"zero_row_update_{idx}_replays_cross_reference_bug",
                bool(
                    call
                    and call.get("tool") == "snowflake.update_rows"
                    and str(args.get("table") or "") == str(item.get("table") or "")
                    and str(args.get("where") or "") == str(item.get("where") or "")
                    and args.get("columns") == item.get("columns")
                    and call_result.get("ok") is True
                    and call_result.get("updated") == item.get("updated")
                ),
                {"expected": item, "actual_call": call},
            ))

    # Exact Slack text pin (used when generic tool_expectations are not
    # applicable, e.g. the NETSUITE branch whose attachment fields render
    # empty because of the cross-reference bug).
    slack_texts = expect.get("slack_texts")
    if isinstance(slack_texts, list):
        posts = [call for call in tool_calls if call.get("tool") == "slack.post_message"]
        actual_texts = [str((call.get("args") or {}).get("text") or "") for call in posts]
        checks.append(_check(
            "slack_texts_match_expected_exactly",
            actual_texts == [str(text) for text in slack_texts]
            and all(
                (call.get("result") or {}).get("ok")
                and str((call.get("args") or {}).get("channel") or "")
                for call in posts
            ),
            {"expected_texts": slack_texts, "actual_posts": posts},
        ))

    # Final live-table state pin (both tables, every variant): row counts must
    # match exactly and each expected row must match a distinct live row.
    snowflake_final = expect.get("snowflake_final")
    if not isinstance(snowflake_final, dict) or not snowflake_final:
        checks.append(_check(
            "expect_snowflake_final_missing",
            False,
            {"reason": "recipe 90817361 variants must pin expect.snowflake_final "
                       "(final RPA.QUEUE / RPA.NETSUITE_QUEUE state)", "expect": expect},
        ))
    else:
        final_tables = ((details.get("final_snapshot") or {}).get("snowflake") or {}).get("tables") or {}
        for table, expected_rows in snowflake_final.items():
            actual_rows = final_tables.get(table)
            if not isinstance(expected_rows, list) or not isinstance(actual_rows, list):
                checks.append(_check(
                    f"snowflake_final_{table}_rows_present",
                    False,
                    {"expected_rows": expected_rows, "actual_rows": actual_rows},
                ))
                continue
            remaining = [row for row in actual_rows if isinstance(row, dict)]
            unmatched: list[Any] = []
            for expected_row in expected_rows:
                match = next(
                    (
                        row for row in remaining
                        if isinstance(expected_row, dict)
                        and all(str(_case_field(row, key)) == str(value) for key, value in expected_row.items())
                    ),
                    None,
                )
                if match is None:
                    unmatched.append(expected_row)
                else:
                    remaining.remove(match)
            checks.append(_check(
                f"snowflake_final_state_matches_{table}",
                len(actual_rows) == len(expected_rows) and not unmatched,
                {
                    "table": table,
                    "expected_rows": expected_rows,
                    "actual_rows": actual_rows,
                    "unmatched_expected": unmatched,
                },
            ))

    return {"ok": _checks_ok(checks), "checks": checks}


def verify_121365920(result: dict[str, Any]) -> dict[str, Any]:
    table_id = "29282"
    col_stage = "ce590e2a_eec4_4dc2_bde2_321f102f3b1d"
    col_record_id = "11fbe9a6_a16d_4d7e_86ea_afe42ec03005"
