    tool_calls = result.get("tool_calls") or []
    raw_execution = details.get("raw_execution") or {}
    seed_message = details.get("seed_message") if isinstance(details.get("seed_message"), dict) else {}
    posts = [call for call in tool_calls if call.get("tool") == "slack.post_message"]

    # Slack outcome pin: 'edit' = chat.update of the SEEDED live message via
    # advanced.ts; 'thread' = catch-branch reply threaded under the seeded ts;
    # 'none' = no Slack call at all.
    interaction = expect.get("slack_interaction")
    if interaction not in {"edit", "thread", "none"}:
        checks.append(_check(
            "expect_slack_interaction_missing",
            False,
            {"reason": "recipe 121365920 variants must pin expect.slack_interaction "
                       "(edit|thread|none)", "expect": expect},
        ))
    elif interaction == "none":
        checks.append(_check(
            "no_slack_call_on_this_branch",
            not posts,
            {"posts": posts},
        ))
    else:
        seed_ts = str(seed_message.get("ts") or "")
        post = posts[0] if posts else None
        args = (post or {}).get("args") or {}
        post_result = (post or {}).get("result") or {}
        checks.append(_check(
            "single_slack_call_on_this_branch",
            len(posts) == 1,
            {"posts": posts},
        ))
        if interaction == "edit":
            checks.append(_check(
                "slack_edit_targets_seeded_message_ts",
                bool(
                    post
                    and seed_ts
                    and str(args.get("ts") or "") == seed_ts
                    and str(args.get("thread_ts") or "") == ""
                    and post_result.get("ok")
                ),
                {"seed_message": seed_message, "post_args": args, "post_result": post_result},
            ))
        else:
            checks.append(_check(
                "slack_thread_reply_targets_seeded_message_ts",
                bool(
                    post
                    and seed_ts
                    and str(args.get("thread_ts") or "") == seed_ts
                    and str(args.get("ts") or "") == ""
                    and post_result.get("ok")
                ),
                {"seed_message": seed_message, "post_args": args, "post_result": post_result},
            ))

    # Catch-branch pin: the forced Slack failure must surface as the recipe's
    # catch payload with the exact error message the IF compares against.
    catch_expect = expect.get("catch")
    if isinstance(catch_expect, dict):
        step_as = str(catch_expect.get("step_as") or "")
        catch_data = (raw_execution.get("data") or {}).get("catch") or {}
        payload = catch_data.get(step_as) if isinstance(catch_data.get(step_as), dict) else {}
        checks.append(_check(
            "catch_payload_carries_expected_message",
            bool(step_as) and str(payload.get("message") or "") == str(catch_expect.get("message") or ""),
            {"expected_catch": catch_expect, "actual_catch_data": catch_data},
        ))

    # Final tracking-table pin: either the stage column was rewritten on the
    # tracked record, or (no-tracking-row branch) the table is untouched.
    final_rows = (
        ((details.get("final_snapshot") or {}).get("workato_db_table") or {})
        .get("tables", {})
        .get(table_id, [])
    )
    final_stage = expect.get("final_stage")
    if isinstance(final_stage, dict):
        record_id = str(final_stage.get("record_id") or "")
        stage = str(final_stage.get("stage") or "")
        target = next(
            (
                row for row in final_rows
                if isinstance(row, dict) and str(row.get(col_record_id) or "") == record_id
            ),
            None,
        )
        checks.append(_check(
            "final_tracking_row_stage_matches",
            bool(target and record_id and str(target.get(col_stage) or "") == stage),
            {"expected": final_stage, "target_row": target, "row_count": len(final_rows)},
        ))
    elif expect.get("final_table_unchanged") is True:
        initial_rows = (
            ((details.get("initial_snapshot") or {}).get("workato_db_table") or {})
            .get("tables", {})
            .get(table_id, [])
        )
        checks.append(_check(
            "tracking_table_unchanged",
            final_rows == initial_rows,
            {"initial_rows": initial_rows, "final_rows": final_rows},
        ))
    else:
        checks.append(_check(
            "expect_final_state_missing",
            False,
            {"reason": "recipe 121365920 variants must pin expect.final_stage or "
                       "expect.final_table_unchanged", "expect": expect},
        ))

    return {"ok": _checks_ok(checks), "checks": checks}


