def verify_88676017(result: dict[str, Any]) -> dict[str, Any]:
    RETURN_FIELDS = ["opportunity_id", "opportunity_name", "opportunity_stage"]
    DISABLED_STEPS = set(range(15, 29))
    base = _verify_replay_recipe(result)
    checks = list(base.get("checks") or [])
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") or {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    if "returned" not in expect:
        checks.append(_check(
            "expect_required_keys_missing",
            False,
            {
                "reason": "every 88676017 variant must declare expect.returned "
                          "(and expect.return_result when a return fires)",
                "expect": expect,
            },
        ))
        return {"ok": False, "checks": checks}
    return_value = raw_execution.get("return_value")
    return_rows = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == "workato_recipe_function.return_result"
    ]
    if expect.get("returned"):
        pinned = expect.get("return_result")
        checks.append(_check(
            "return_value_matches_expected",
            isinstance(pinned, dict)
            and sorted(pinned.keys()) == RETURN_FIELDS
            and return_value == pinned
            and len(return_rows) == 1,
            {
                "expected_return_result": pinned,
                "actual_return_value": return_value,
                "return_rows": return_rows,
            },
        ))
    else:
        # Fall-through paths (no open opp / no account link) end WITHOUT any
        # return_result because every later return lives in the disabled region.
        checks.append(_check(
            "no_return_result_fired",
            return_value is None and not return_rows,
            {"actual_return_value": return_value, "return_rows": return_rows},
        ))
    executed_disabled = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") and row.get("number") in DISABLED_STEPS
    ]
    skipped_rows = [row for row in trace if isinstance(row, dict) and row.get("skipped")]
    checks.append(_check(
        "author_disabled_steps_never_execute",
        not executed_disabled
        and all(row.get("number") in DISABLED_STEPS for row in skipped_rows),
        {"executed_disabled": executed_disabled, "skipped_rows": skipped_rows},
    ))
    return {"ok": _checks_ok(checks), "checks": checks}


def verify_118153797(result: dict[str, Any]) -> dict[str, Any]:
    base = _verify_replay_recipe(result)
    checks = list(base.get("checks") or [])
