    action_rows = [
        row for row in trace
        if isinstance(row, dict) and row.get("keyword") == "action" and row.get("tool")
    ]
    checks.append(_check(
        "trace_tool_sequence_matches_expected_path",
        [row.get("tool") for row in action_rows] == expect.get("trace_tools"),
        {
            "expected_trace_tools": expect.get("trace_tools"),
            "actual_trace_tools": [row.get("tool") for row in action_rows],
        },
    ))

