    checks.append(_check(
        "stop_behavior_matches_expected",
        bool(stop_rows) is bool(expect.get("stopped")),
        {"expected_stopped": expect.get("stopped"), "stop_rows": stop_rows},
    ))
    if expect.get("stopped"):
        checks.append(_check(
            "stop_step_number_matches_expected",
            len(stop_rows) == 1
            and str(stop_rows[0].get("number")) == str(expect.get("stop_step_number")),
            {"expected_stop_step_number": expect.get("stop_step_number"), "stop_rows": stop_rows},
        ))

    update_rows = [row for row in action_rows if row.get("tool") == "salesforce.update_record"]
    expected_updates = expect.get("sf_update_fields_exact") if isinstance(expect.get("sf_update_fields_exact"), list) else []
    updates_ok = len(update_rows) == len(expected_updates)
    update_mismatches: list[dict[str, Any]] = []
    if updates_ok:
        for row, expected_update in zip(update_rows, expected_updates):
            args = row.get("args") if isinstance(row.get("args"), dict) else {}
            row_result = row.get("result") if isinstance(row.get("result"), dict) else {}
            if not (
                isinstance(expected_update, dict)
                and str(args.get("sobject") or "") == "Campaign_Activity__c"
                and str(args.get("id") or "") == str(expected_update.get("id") or "")
                and args.get("fields") == expected_update.get("fields")
                and row_result.get("ok") is True
            ):
                updates_ok = False
                update_mismatches.append({"expected": expected_update, "actual": row})
    checks.append(_check(
        "salesforce_update_args_match_exactly",
        updates_ok,
        {
            "expected_updates": expected_updates,
            "actual_updates": [
                {"args": row.get("args"), "ok": (row.get("result") or {}).get("ok")}
                for row in update_rows
            ],
            "mismatches": update_mismatches,
        },
    ))

    query_rows = [row for row in action_rows if row.get("tool") == "workato_smart_list.query_list"]
    smart_list = expect.get("smart_list")
