def verify_88707765(result: dict[str, Any]) -> dict[str, Any]:
    base = _verify_replay_recipe(result)
    checks = list(base.get("checks") or [])
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") or {}
    missing_keys = [key for key in ("http_status_code", "response") if key not in expect]
    if missing_keys:
        checks.append(_check(
            "expect_required_keys_missing",
            False,
            {
                "reason": "every 88707765 variant must declare expect.http_status_code and expect.response",
                "missing_keys": missing_keys,
                "expect": expect,
            },
        ))
        return {"ok": False, "checks": checks}
    composite_failed_count = expect.get("composite_failed_count")
    if isinstance(composite_failed_count, int) and composite_failed_count > 0:
        # allOrNone=false opt-in: exactly ONE failed trace row is allowed and
        # it must be the composite update carrying exactly the declared number
        # of failedRecords, each a real per-record failure (success:false with
        # a non-empty errors list). Any other failed row still fails the run.
        trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
        failed_rows = [
            row
            for row in trace
            if isinstance(row, dict)
            and isinstance(row.get("result"), dict)
            and row["result"].get("ok") is False
        ]
        composite_rows = [
            row
            for row in failed_rows
            if row.get("tool") == "salesforce.update_record"
            and isinstance(row["result"].get("failedRecords"), list)
        ]
        composite_failed_items = (
            composite_rows[0]["result"].get("failedRecords") or [] if len(composite_rows) == 1 else []
        )
        replacement = _check(
            "raw_recipe_executed_without_harness_error_allowing_composite_partial_failure",
            len(failed_rows) == 1
            and len(composite_rows) == 1
            and len(composite_failed_items) == composite_failed_count
            and all(
                isinstance(item, dict)
                and item.get("success") is False
                and bool(item.get("errors") or [])
                for item in composite_failed_items
            ),
            {
                "expected_composite_failed_count": composite_failed_count,
                "failed_trace_rows": failed_rows,
            },
        )
        checks = [
            replacement
            if check.get("name") == "raw_recipe_executed_without_harness_error"
            else check
            for check in checks
        ]
    return_value = raw_execution.get("return_value")
    checks.append(_check(
        "api_response_matches_expected_exactly",
        return_value == expect.get("response"),
        {"expected_response": expect.get("response"), "actual_return_value": return_value},
    ))
    response_calls = [
        call
        for call in result.get("tool_calls") or []
        if isinstance(call, dict) and call.get("tool") == "workato_api_platform.return_response"
    ]
    last_response = response_calls[-1] if response_calls else None
    last_result = (last_response or {}).get("result") or {}
    checks.append(_check(
        "return_response_call_carries_expected_body_and_status",
        bool(
            last_response
            and last_result.get("ok") is True
            and last_result.get("response") == expect.get("response")
            and str(last_result.get("http_status_code") or "") == str(expect.get("http_status_code") or "")
        ),
        {
            "expected_http_status_code": expect.get("http_status_code"),
            "expected_response": expect.get("response"),
            "actual_call": last_response,
        },
    ))
    cleanup = details.get("cleanup_response")
    if cleanup is not None:
        checks.append(_check(
            "salesforce_cleanup_removed_owned_records",
            isinstance(cleanup, dict)
            and cleanup.get("ok") is True
            and not (cleanup.get("leftovers") or []),
            {"cleanup_response": cleanup},
        ))
    return {"ok": _checks_ok(checks), "checks": checks}


