def verify_91339479(result: dict[str, Any]) -> dict[str, Any]:
    base = _verify_replay_recipe(result)
    checks = list(base.get("checks") or [])
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") or {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    action_rows = [row for row in trace if isinstance(row, dict) and row.get("keyword") == "action"]
    catch_payloads = (raw_execution.get("data") or {}).get("catch") or {}
    branch = expect.get("menu_branch")
    branch_steps = {
        "user": ("4", "146dcac6", "5", "8a836e8a"),
        "account": ("7", "2284ebd6", "8", "6c4a1f08"),
        "empty": ("7", "2284ebd6", "8", "6c4a1f08"),
        "contact": ("10", "7942ec9f", "11", "54230477"),
    }
    if branch not in {"user", "account", "contact", "none", "empty", "catch"}:
        checks.append(_check(
            "expect_menu_branch_invalid",
            False,
            {
                "reason": "every 91339479 variant must pin expect.menu_branch "
                          "(user|account|contact|none|empty|catch)",
                "value": branch,
                "expect": expect,
            },
        ))
        return {"ok": False, "checks": checks}
    if branch == "none":
        checks.append(_check(
            "unmatched_typeahead_ran_zero_actions",
            not action_rows and raw_execution.get("executed_action_count") == 0,
            {
                "reason": "the three sibling IFs are not elsif: an unmatched "
                          "typeahead.name must leave the try body action-less",
                "trace": trace,
            },
        ))
    elif branch == "catch":
        missing = [key for key in ("logger_message", "catch_type", "catch_error") if not expect.get(key)]
        if missing:
            checks.append(_check(
                "expect_catch_keys_missing",
                False,
                {"reason": "catch variant must pin logger_message/catch_type/catch_error",
                 "missing_keys": missing, "expect": expect},
            ))
            return {"ok": False, "checks": checks}
        row = action_rows[0] if len(action_rows) == 1 else {}
        checks.append(_check(
            "forced_error_ran_only_the_step13_catch_logger",
            len(action_rows) == 1
            and str(row.get("number")) == "13"
            and row.get("as") == "52c21140"
            and row.get("tool") == "workato_runtime.log_message"
            and (row.get("args") or {}).get("message") == expect.get("logger_message"),
            {
                "reason": "the forced 2284ebd6 failure must skip the search/menu "
                          "steps and run exactly the catch logger with the pinned "
                          "'<type> : <message>' text",
                "expected_message": expect.get("logger_message"),
                "action_rows": action_rows,
            },
        ))
        checks.append(_check(
            "catch_payload_recorded_forced_error",
            catch_payloads == _expected_menu_catch_payload(expect),
            {
                "expected_type": expect.get("catch_type"),
                "expected_message": expect.get("catch_error"),
                "actual_catch": catch_payloads,
            },
        ))
        checks.append(_check(
            "logger_message_renders_type_colon_message",
            expect.get("logger_message") == "%s : %s" % (expect.get("catch_type"), expect.get("catch_error")),
            {
                "reason": "pins the raw logger formula '#{catch.type} : #{catch.message}'",
                "logger_message": expect.get("logger_message"),
            },
        ))
    else:
        menu_options = expect.get("menu_options")
        if not isinstance(menu_options, list):
            checks.append(_check(
                "expect_menu_options_missing",
                False,
                {"reason": "menu branches must pin the exact ordered expect.menu_options list",
                 "expect": expect},
            ))
            return {"ok": False, "checks": checks}
        search_number, search_as, menu_number, menu_as = branch_steps[branch]
        search_row = action_rows[0] if len(action_rows) == 2 else {}
        menu_row = action_rows[1] if len(action_rows) == 2 else {}
        checks.append(_check(
            "branch_ran_exactly_its_two_pinned_steps",
            len(action_rows) == 2
            and str(search_row.get("number")) == search_number
            and search_row.get("as") == search_as
            and search_row.get("tool") == "salesforce.search_records"
            and str(menu_row.get("number")) == menu_number
            and menu_row.get("as") == menu_as
            and menu_row.get("tool") == "slack_bot.generate_menu_options",
            {
                "reason": "the three menu branches share identical tool names; "
                          "only the step number/as pair proves the pinned IF fired",
                "expected_steps": [
                    [search_number, search_as, "salesforce.search_records"],
                    [menu_number, menu_as, "slack_bot.generate_menu_options"],
                ],
                "action_rows": action_rows,
            },
        ))
        expected_menu_args = {"options": menu_options, "option_groups": [{"options": menu_options}]}
        checks.append(_check(
            "menu_args_pin_flattened_options_and_option_groups",
            (menu_row.get("args") or {}) == expected_menu_args,
            {
                "reason": "option_groups group-expansion groundtruth: args must carry "
                          "the flattened options AND option_groups:[{options}] exactly",
                "expected_args": expected_menu_args,
                "actual_args": menu_row.get("args"),
            },
        ))
        expected_menu_result = {"ok": True, "options": menu_options,
                                "option_groups": [{"options": menu_options}]}
        checks.append(_check(
            "menu_result_echoes_option_payload_exactly",
            (menu_row.get("result") or {}) == expected_menu_result,
            {"expected_result": expected_menu_result, "actual_result": menu_row.get("result")},
        ))
        records = (search_row.get("result") or {}).get("records")
        records = records if isinstance(records, list) else []
        derived = [
            {"label": str((record or {}).get("Name") or ""), "value": str((record or {}).get("Id") or "")}
            for record in records
            if isinstance(record, dict)
        ]
        checks.append(_check(
            "menu_options_map_one_per_search_record",
            derived == menu_options,
            {
                "reason": "group expansion must emit exactly one {label: Name, "
                          "value: Id} option per search record, in result order",
                "derived_from_search": derived,
                "expected_menu_options": menu_options,
            },
        ))
        if branch == "empty":
            checks.append(_check(
                "empty_prefix_produced_zero_options",
                menu_options == [] and records == [],
                {"menu_options": menu_options, "search_records": records},
            ))
        else:
            live_ids_ok = bool(menu_options) and all(
                isinstance(option, dict)
                and str(option.get("label") or "").strip()
                and len(str(option.get("value") or "")) in (15, 18)
                and str(option.get("value") or "").isalnum()
                for option in menu_options
            )
            checks.append(_check(
                "menu_option_values_are_live_salesforce_ids",
                live_ids_ok,
                {
                    "reason": "matched menus must carry at least one option whose "
                              "value is a live 15/18-char Salesforce id",
                    "menu_options": menu_options,
                },
            ))
    if branch != "catch":
        checks.append(_check(
            "no_catch_fired_on_success_path",
            not catch_payloads,
            {"actual_catch": catch_payloads},
        ))
    initial_snapshot = details.get("initial_snapshot")
    final_snapshot = details.get("final_snapshot")
    if initial_snapshot or final_snapshot:
        checks.append(_check(
            "salesforce_untouched_by_read_only_menu_recipe",
            bool(initial_snapshot) and initial_snapshot == final_snapshot,
            {"initial_snapshot": initial_snapshot, "final_snapshot": final_snapshot},
        ))
    return {"ok": _checks_ok(checks), "checks": checks}


