def _verify_registration_sheet_upsert(result: dict[str, Any]) -> dict[str, Any]:
    """Shared strict contract for the 131392307/131392306 twin pair."""
    base = _verify_replay_recipe(result)
    checks = list(base.get("checks") or [])
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") or {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    missing = [
        key
        for key in ("trigger_filter_matched", "final_sheet", "catch_used", "executed_action_count")
        if key not in expect
    ]
    if expect.get("catch_used") is True and not str(expect.get("forced_error_message") or "").strip():
        missing.append("forced_error_message")
    if missing:
        checks.append(_check(
            "expect_contract_missing_keys",
            False,
            {"missing": missing, "reason": "strict registration-upsert verification requires them"},
        ))
        return {"ok": False, "checks": checks}
    checks.append(_check(
        "trigger_filter_outcome_matches_expected",
        raw_execution.get("trigger_filter_matched") is expect.get("trigger_filter_matched"),
        {
            "expected": expect.get("trigger_filter_matched"),
            "actual": raw_execution.get("trigger_filter_matched"),
        },
    ))

    final_sheet = expect.get("final_sheet") if isinstance(expect.get("final_sheet"), dict) else {}
    snapshot = (details.get("final_snapshot") or {}).get("google_sheets") or {}
    rows = snapshot.get("rows") if isinstance(snapshot.get("rows"), list) else []
    checks.append(_check(
        "final_sheet_headers_match_expected",
        snapshot.get("headers") == final_sheet.get("headers"),
        {"expected_headers": final_sheet.get("headers"), "actual_headers": snapshot.get("headers")},
    ))
    checks.append(_check(
        "final_sheet_row_count_matches",
        len(rows) == final_sheet.get("row_count"),
        {"expected": final_sheet.get("row_count"), "actual": len(rows), "rows": rows},
    ))
    for idx, item in enumerate(final_sheet.get("rows") or []):
        if not isinstance(item, dict) or not isinstance(item.get("fields"), dict):
            checks.append(_check(f"final_sheet_expected_row_{idx}_is_object", False, {"value": item}))
            continue
        fields = item["fields"]
        match_fields = item.get("match_fields") if isinstance(item.get("match_fields"), list) else list(fields.keys())
        matching = [
            row for row in rows
            if isinstance(row, dict)
            and all(str(row.get(field)) == str(fields.get(field)) for field in match_fields)
        ]
        checks.append(_check(
            f"final_sheet_expected_row_{idx}_matches",
            bool(matching and all(str(matching[0].get(key)) == str(value) for key, value in fields.items())),
            {"expected": fields, "match_fields": match_fields, "matching_rows": matching},
        ))

    stop_markers = [
        row for row in trace
        if isinstance(row, dict) and row.get("keyword") == "stop" and row.get("stopped") is True
    ]
    if expect.get("catch_used") is True:
        forced = str(expect.get("forced_error_message") or "")
        error_calls = [
            row for row in trace
            if isinstance(row, dict) and row.get("tool") == "workato_service.call_service"
        ]
        error_messages = [
            str(((row.get("args") or {}).get("request") or {}).get("error_message") or "")
            for row in error_calls
        ]
        checks.append(_check(
            "catch_error_report_carries_forced_message",
            bool(error_messages and all(forced in message for message in error_messages)),
            {"forced_error_message": forced, "actual_error_messages": error_messages},
        ))
        checks.append(_check(
            "catch_stopped_with_single_trailing_stop_marker",
            bool(len(stop_markers) == 1 and trace and trace[-1] is stop_markers[0]),
            {"stop_markers": stop_markers, "trace_tail": trace[-1] if trace else None},
        ))
    else:
        checks.append(_check(
            "no_stop_marker_on_non_catch_path",
            not stop_markers,
            {"stop_markers": stop_markers},
        ))
    return {"ok": _checks_ok(checks), "checks": checks}


