def verify_106478365(result: dict[str, Any]) -> dict[str, Any]:
    base = _verify_replay_recipe(result)
    checks = list(base.get("checks") or [])
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") or {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    missing = [
        key for key in ("catch", "skipped_steps", "final_table_14696", "return_result")
        if key not in expect
    ]
    if missing:
        checks.append(_check(
            "expect_required_keys_missing",
            False,
            {
                "reason": "every 106478365 variant must pin expect.catch, "
                          "expect.skipped_steps, expect.final_table_14696 and "
                          "expect.return_result",
                "missing_keys": missing,
                "expect": expect,
            },
        ))
        return {"ok": False, "checks": checks}
    # Reached-but-skipped markers for the disabled steps 9/10/11 — exact
    # per-step counts (step 9 sits inside the foreach: one marker per entry).
    actual_skipped: dict[str, int] = {}
    for row in trace:
        if isinstance(row, dict) and row.get("skipped") is True:
            key = str(row.get("number"))
            actual_skipped[key] = actual_skipped.get(key, 0) + 1
    expected_skipped = {
        str(key): int(value) for key, value in (expect.get("skipped_steps") or {}).items()
    }
    checks.append(_check(
        "disabled_steps_reached_but_skipped_exactly",
        actual_skipped == expected_skipped,
        {"expected_skipped_steps": expected_skipped, "actual_skipped_steps": actual_skipped},
    ))
    checks.append(_check(
        "no_disabled_step_ever_executed",
        not any(
            isinstance(row, dict) and row.get("tool") and row.get("number") in (9, 10, 11)
            for row in trace
        ),
        {"trace": trace},
    ))
    # Terminal return_result at step 15, exactly once, returning {}.
    return_rows = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == "workato_recipe_function.return_result"
    ]
    checks.append(_check(
        "return_fired_once_at_step_15",
        len(return_rows) == 1 and str(return_rows[0].get("number")) == "15",
        {"return_rows": return_rows},
    ))
    checks.append(_check(
        "return_value_matches_expected_exactly",
        raw_execution.get("return_value") == expect.get("return_result"),
        {
            "expected_return_result": expect.get("return_result"),
            "actual_return_value": raw_execution.get("return_value"),
        },
    ))
    # Exact final Error History table (the recipe's only persistent effect).
    final_snapshot = details.get("final_snapshot") or {}
    final_rows = (
        (final_snapshot.get("workato_db_table") or {}).get("tables") or {}
    ).get("14696")
    checks.append(_check(
        "final_error_history_rows_match_exactly",
        final_rows == expect.get("final_table_14696"),
        {"expected_rows": expect.get("final_table_14696"), "actual_rows": final_rows},
    ))
    # The catch branch: pinned via the step-14 post; non-catch variants must
    # never reach step 14, catch variants must never run the step-12 update.
    catch_rows = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == "slack.post_message" and row.get("number") == 14
    ]
    update_rows = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == "workato_db_table.update_record"
    ]
    if expect.get("catch") is True:
        checks.append(_check(
            "catch_posted_recipe_broken_dm_once",
            len(catch_rows) == 1
            and str(catch_rows[0].get("number")) == str(expect.get("catch_post_step_number")),
            {
                "expected_catch_post_step_number": expect.get("catch_post_step_number"),
                "catch_rows": catch_rows,
            },
        ))
        checks.append(_check(
            "catch_variant_never_marked_row_resolved",
            not update_rows,
            {"update_rows": update_rows},
        ))
    else:
        checks.append(_check(
            "no_catch_post_on_success_path",
            not catch_rows,
            {"catch_rows": catch_rows},
        ))
    # The data-owner lookup table is read-only on every branch.
    initial_snapshot = details.get("initial_snapshot") or {}
    checks.append(_check(
        "lookup_table_untouched",
        bool(initial_snapshot.get("lookup_table"))
        and initial_snapshot.get("lookup_table") == final_snapshot.get("lookup_table"),
        {
            "initial_lookup": initial_snapshot.get("lookup_table"),
            "final_lookup": final_snapshot.get("lookup_table"),
        },
    ))
    return {"ok": _checks_ok(checks), "checks": checks}


def verify_130704674(result: dict[str, Any]) -> dict[str, Any]:
    base = _verify_replay_recipe(result)
    checks = list(base.get("checks") or [])
