def verify_125461407(result: dict[str, Any]) -> dict[str, Any]:
    replay = _verify_replay_recipe(result)
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") or {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    checks = list(replay.get("checks") or [])

    required = ("slack_text", "trace_tools", "channel_source")
    missing = [key for key in required if key not in expect]
    if missing:
        checks.append(_check(
            "expect_required_keys_missing",
            False,
            {"reason": f"every 125461407 variant must pin {missing}", "expect": expect},
        ))
        return {"ok": False, "checks": checks}

    actual_trace_tools = [
        row.get("tool")
        for row in trace
        if isinstance(row, dict) and row.get("keyword") == "action" and row.get("tool")
    ]
    checks.append(_check(
        "trace_tool_sequence_matches_expected",
        actual_trace_tools == expect.get("trace_tools"),
        {
            "reason": "the ordered declare/insert/post sequence pins which presence "
                      "IFs fired (inserts are workato_runtime steps outside "
                      "allowed_tools, so the strict block alone cannot see them)",
            "expected_trace_tools": expect.get("trace_tools"),
            "actual_trace_tools": actual_trace_tools,
        },
    ))

    slack_rows = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == "slack.post_message"
    ]
    slack_args = (slack_rows[0].get("args") or {}) if slack_rows else {}
    checks.append(_check(
        "slack_post_text_matches_exactly",
        len(slack_rows) == 1
        and slack_args.get("text") == expect.get("slack_text")
        and bool(slack_args.get("channel")),
        {
            "reason": "exact render: pretext + title + attachment_text + one "
                      "'Name: value' line per inserted field, posted to the "
                      "(non-empty) override channel",
            "expected_text": expect.get("slack_text"),
            "slack_rows": slack_rows,
        },
    ))

    message = ((details.get("trigger") or {}).get("message") or {})
    error_channel_blank = not str(message.get("error_channel") or "").strip()
    expected_source = expect.get("channel_source")
    checks.append(_check(
        "channel_source_consistent_with_trigger",
        (expected_source == "account_property") == error_channel_blank
        and expected_source in ("message", "account_property"),
        {
            "reason": "channel = message.error_channel.presence || account property: "
                      "a blank error_channel and only a blank one takes the fallback "
                      "arm (the property is seeded exactly in that case)",
            "expected_channel_source": expected_source,
            "trigger_error_channel": message.get("error_channel"),
        },
    ))

    stop_rows = [row for row in trace if isinstance(row, dict) and row.get("stopped") is True]
    checks.append(_check(
        "no_stop_occurred",
        not stop_rows,
        {"reason": "125461407 has no stop steps; every variant runs to the post", "stop_rows": stop_rows},
    ))

    return {"ok": _checks_ok(checks), "checks": checks}


