            for row_idx, expected_row in enumerate(spec.get("rows") or []):
                if not isinstance(expected_row, dict) or not match_fields:
                    checks.append(_check(
                        f"final_{table_key}_expected_row_{row_idx}_well_formed",
                        False,
                        {"expected_row": expected_row, "match_fields": match_fields},
                    ))
                    continue
