# Verifier fragment for recipe 106603524 (recipe function: AccountList ->
# account_ids_string pluck/join -> two aggregate SOQL COUNT queries over live
# Support_Ticket__c (open tickets / open >20 days, SELECT aliases) -> two
# smart lists -> LEFT JOIN query -> return result.SupportTickets; whole body
# in TRY, CATCH(max_retry 3) -> STOP stop_with_error).
# To be merged into src/benchmark/verifier.py by the coordinating session.
# Uses only helpers already defined there: _verify_replay_recipe, _check.
#
# SEMANTIC TRAPS encoded via exact expects:
# - expect.tool_expectations pins the two RESOLVED aggregate SOQL texts
#   verbatim (IsDeleted = FALSE evaluated on live read-back via read_fields,
#   NOT IN ('Closed', 'Resolved'), Account__c IN ('<live ids>') built from
#   the pluck/join string -- IN ('') on the empty-input branch -- and the
#   Days_Open__c > 20 leaf that differentiates the second query).
# - expect.query_rows pins the exact LEFT-JOIN output: a JOIN hit carries an
#   integer OpenTicketsMore20days, a LEFT-JOIN miss carries null, and the
#   empty-input branch carries [] (create_lists row_counts 0/0 prove the
#   lists were built and empty, not skipped).
# - expect.final_result pins the exact return_result payload (the
#   ____source-mapped SupportTickets rows, null for the JOIN-miss column).
# - the catch variant (sanctioned fault injection on 596c386d) pins the
#   engine-canonical catch payload {type: RawRecipeExecutionError, message}
#   via step_outputs and requires the stop row (11 / db452987) to be the
#   FINAL trace row; trace stop rows carry no stop_reason.
# - live seeded records are deleted in a finally block; cleanup must report
#   zero leftovers.


def verify_106603524(result: dict[str, Any]) -> dict[str, Any]:
    CATCH_STEP = "baa77910"
    replay = _verify_replay_recipe(result)
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") or {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    checks = list(replay.get("checks") or [])

    expected_sqls = expect.get("smart_list_sqls")
    actual_sqls = [
        str((row.get("args") or {}).get("sql"))
        for row in trace
        if isinstance(row, dict) and row.get("tool") == "workato_smart_list.query_list"
    ]
    checks.append(_check(
        "smart_list_sql_sequence_matches",
        isinstance(expected_sqls, list) and actual_sqls == expected_sqls,
        {
            "reason": "the resolved LEFT JOIN SQL (list names + qualified columns from "
                      "list_name/columns pills) is pinned verbatim; [] on the catch path",
            "expected_sqls": expected_sqls,
            "actual_sqls": actual_sqls,
        },
    ))

    expected_creates = expect.get("create_lists")
    actual_creates = [
        {
            "list_name": (row.get("result") or {}).get("list_name"),
            "row_count": (row.get("result") or {}).get("row_count"),
        }
        for row in trace
        if isinstance(row, dict) and row.get("tool") == "workato_smart_list.create_list"
    ]
    checks.append(_check(
        "create_list_sequence_matches",
        isinstance(expected_creates, list) and actual_creates == expected_creates,
        {
            "reason": "both smart lists materialize the aggregate record sets in order "
                      "(OpenTickets then OpenTicketsMore20days); row_count 0 on the "
                      "empty-input branch proves the lists were built empty, not skipped",
            "expected_create_lists": expected_creates,
            "actual_create_lists": actual_creates,
        },
    ))

    query_rows_actual = [
        (row.get("result") or {}).get("rows")
        for row in trace
        if isinstance(row, dict) and row.get("tool") == "workato_smart_list.query_list"
    ]
    if expect.get("query_rows") is None:
        checks.append(_check(
            "left_join_query_never_ran",
            not query_rows_actual,
            {
                "reason": "the catch path stops before step 8",
                "actual_query_results": query_rows_actual,
            },
        ))
    else:
        checks.append(_check(
            "left_join_rows_match_exactly",
            len(query_rows_actual) == 1 and query_rows_actual[0] == expect.get("query_rows"),
            {
                "reason": "the joined rows are pinned exactly: integer counts on JOIN hits, "
                          "null OpenTicketsMore20days on LEFT-JOIN misses, [] when the "
                          "account filter matched nothing",
                "expected_rows": expect.get("query_rows"),
                "actual_query_results": query_rows_actual,
            },
        ))

    checks.append(_check(
        "final_result_matches_exactly",
        raw_execution.get("return_value") == expect.get("final_result"),
        {
            "reason": "return_result carries the exact ____source-mapped SupportTickets "
                      "rows (null on the catch path, [] SupportTickets on the empty branch)",
            "expected_final_result": expect.get("final_result"),
            "actual_return_value": raw_execution.get("return_value"),
        },
    ))

    stop_rows = [row for row in trace if isinstance(row, dict) and row.get("stopped") is True]
    catch_payload = (raw_execution.get("step_outputs") or {}).get(CATCH_STEP)
    if expect.get("stopped") is True:
        checks.append(_check(
            "catch_stop_is_final_trace_row",
            len(stop_rows) == 1
            and bool(trace)
            and trace[-1] is stop_rows[0]
            and str(stop_rows[0].get("as") or "") == str(expect.get("stop_step_as"))
            and str(stop_rows[0].get("number")) == str(expect.get("stop_step_number")),
            {
                "reason": "the forced 596c386d failure must divert to the catch and end at "
                          "the stop_with_error step 11/db452987 (trace stop rows carry no "
                          "stop_reason; the reason pills are pinned via the catch payload)",
                "expected_stop": {
                    "as": expect.get("stop_step_as"),
                    "number": expect.get("stop_step_number"),
                },
                "stop_rows": stop_rows,
            },
        ))
        checks.append(_check(
            "catch_payload_matches_exactly",
            catch_payload == expect.get("catch"),
            {
                "reason": "the stop_reason interpolates '#{catch.type} : #{catch.message}': "
                          "the engine-canonical payload {type: RawRecipeExecutionError, "
                          "message: <forced error>} is pinned exactly",
                "expected_catch": expect.get("catch"),
                "actual_catch": catch_payload,
            },
        ))
    else:
        checks.append(_check(
            "no_stop_or_catch_occurred",
            not stop_rows and catch_payload is None,
            {
                "reason": "happy paths run the whole try body; the catch never fires",
                "stop_rows": stop_rows,
                "actual_catch": catch_payload,
            },
        ))

    cleanup_response = details.get("cleanup_response") or {}
    checks.append(_check(
        "live_salesforce_seed_records_cleaned_up",
        bool(cleanup_response.get("ok")) and not cleanup_response.get("leftovers"),
        {"cleanup_response": cleanup_response},
    ))

    return {"ok": _checks_ok(checks), "checks": checks}


# Verifier fragment for recipe 110075264 (recipe function: primary
