# Verifier fragment for recipe 123859779 (API-platform Gong meetings endpoint:
# request.sfdcAccountId -> strict SOQL search over the Gong_Call__c stand-in
# "Gong__Primary_Account__c = '<id>' AND CreatedDate = LAST_N_DAYS:90 ORDER BY
# CreatedDate DESC" -> IF size>0 return_response 200 {data/rawSources/success}
# ELSE STOP; CATCH -> return_response 200 {error, success:false}).
# To be merged into src/benchmark/verifier.py by the coordinating session.
# Uses only helpers already defined there: _verify_replay_recipe, _check.
#
# SEMANTIC TRAPS encoded via exact expects:
# - response.success is the engine-canonical STRING 'true'/'false' (the raw
#   input strings resolve verbatim; no boolean_conversion in replay).
# - response.data/rawSources are ____source-mapped over the DESC-ordered
#   records: expect.response pins BOTH arrays byte-exact in reverse seed-phase
#   order; the CreatedDate strictly-descending check fails the run on a 1s
#   timestamp tie (phase-spaced seeding must never tie -- 89731033 precedent).
# - the forced-error CATCH raises BEFORE the search resolves its args: no
#   salesforce trace row may exist, and response.error must equal the pinned
#   catch message verbatim.
# - the ELSE path is proven by an owned decoy call for a DIFFERENT account:
#   every returned record must carry the trigger account id, so a dropped
#   account-equality leaf (non-strict silent-drop hazard) fails result_count.


def verify_123859779(result: dict[str, Any]) -> dict[str, Any]:
    replay = _verify_replay_recipe(result)
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") or {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    step_outputs = raw_execution.get("step_outputs") if isinstance(raw_execution.get("step_outputs"), dict) else {}
    trigger = details.get("trigger") if isinstance(details.get("trigger"), dict) else {}
    account_id = str((trigger.get("request") or {}).get("sfdcAccountId") or "")
    checks = list(replay.get("checks") or [])

    sf_rows = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == "salesforce.search_records"
    ]
    forced = isinstance(details.get("force_action_error"), dict)
    checks.append(_check(
        "search_executed_exactly_when_not_forced",
        len(sf_rows) == (0 if forced else 1),
        {
            "reason": "force_action_error on 9126ea78 raises BEFORE arg resolution (no "
                      "salesforce trace row); every other variant runs the live search once",
            "forced": forced,
            "sf_rows": [{"as": row.get("as"), "args": row.get("args")} for row in sf_rows],
        },
    ))

    if sf_rows:
        args = sf_rows[0].get("args") or {}
        expected_query = (
            f"Gong__Primary_Account__c = '{account_id}' AND CreatedDate = LAST_N_DAYS:90 "
            "ORDER BY CreatedDate DESC"
        )
        checks.append(_check(
            "search_query_is_verbatim_strict_soql",
            args.get("query") == expected_query
            and args.get("sobject") == "Gong__Gong_Call__c"
            and str(args.get("limit")) == "20",
            {
                "reason": "the SOQL text interpolates request.sfdcAccountId verbatim; the "
                          "LAST_N_DAYS:90 literal and ORDER BY evaluate under "
                          "strict_soql_conditions only",
                "expected_query": expected_query,
                "actual_args": args,
            },
        ))
        records = (sf_rows[0].get("result") or {}).get("records") or []
        accounts = [
            str((row.get("fields") if isinstance(row.get("fields"), dict) else row).get("Gong__Primary_Account__c") or "")
            for row in records
            if isinstance(row, dict)
        ]
        checks.append(_check(
            "search_result_records_all_match_trigger_account",
            bool(account_id) and all(value == account_id for value in accounts),
            {
                "reason": "the seeded decoy call belongs to a DIFFERENT owned account; any "
                          "off-account record means the equality leaf was dropped "
                          "(non-strict silent-drop hazard)",
                "trigger_account": account_id,
                "record_accounts": accounts,
            },
        ))
        created_values = [
            str((row.get("fields") if isinstance(row.get("fields"), dict) else row).get("CreatedDate") or "")
            for row in records
            if isinstance(row, dict)
        ]
        checks.append(_check(
            "search_result_created_date_strictly_descending",
            all(created_values[idx] > created_values[idx + 1] for idx in range(len(created_values) - 1)),
            {
                "reason": "ORDER BY CreatedDate DESC ground truth requires strictly distinct "
                          "timestamps (1s SF granularity); phase-spaced seeding must never "
                          "tie -- a tie makes the response order nondeterministic and the "
                          "run must fail",
                "created_date_values": created_values,
            },
        ))

    stop_rows = [row for row in trace if isinstance(row, dict) and row.get("keyword") == "stop"]
    if expect.get("stopped"):
        checks.append(_check(
            "else_branch_stopped_at_step_7",
            len(stop_rows) == 1
            and stop_rows[0].get("stopped") is True
            and str(stop_rows[0].get("as") or "") == str(expect.get("stop_step_as") or "")
            and stop_rows[0].get("number") == expect.get("stop_step_number"),
            {
                "reason": "zero matching calls -> ELSE -> STOP e64c4396 (step 7, "
                          "stop_with_error true; the engine trace records stopped:true and "
                          "renders no stop_reason)",
                "expected_stop": {
                    "as": expect.get("stop_step_as"),
                    "number": expect.get("stop_step_number"),
                },
                "stop_rows": stop_rows,
            },
        ))
        checks.append(_check(
            "stopped_run_returns_no_response",
            raw_execution.get("return_value") is None
            and not any(
                isinstance(row, dict) and row.get("tool") == "workato_api_platform.return_response"
                for row in trace
            ),
            {
                "reason": "the STOP path never reaches either return_response",
                "return_value": raw_execution.get("return_value"),
            },
        ))
    else:
        checks.append(_check(
            "no_stop_row_on_response_paths",
            not stop_rows,
            {"reason": "return_response is terminal but is not a STOP", "stop_rows": stop_rows},
        ))
        response_rows = [
            row for row in trace
            if isinstance(row, dict) and row.get("tool") == "workato_api_platform.return_response"
        ]
        checks.append(_check(
            "return_value_matches_expected_response_exactly",
            len(response_rows) == 1
            and raw_execution.get("return_value") == expect.get("response")
            and (response_rows[0].get("result") or {}).get("response") == expect.get("response")
            and str((response_rows[0].get("result") or {}).get("http_status_code") or "") == "200",
            {
                "reason": "the 200 response body is the recipe's observable artifact: exact "
                          "data/rawSources arrays in CreatedDate DESC order (or the catch "
                          "{error, success:'false'} body), success as the engine-canonical "
                          "string",
                "expected_response": expect.get("response"),
                "return_value": raw_execution.get("return_value"),
                "response_rows": response_rows,
            },
        ))

    if forced:
        catch_payload = step_outputs.get("18f2fc6d") if isinstance(step_outputs.get("18f2fc6d"), dict) else {}
        checks.append(_check(
            "catch_payload_matches_forced_error",
            catch_payload.get("type") == "RawRecipeExecutionError"
            and str(catch_payload.get("message") or "") == str(expect.get("catch_message") or "")
            and (expect.get("response") or {}).get("error") == str(expect.get("catch_message") or ""),
            {
                "reason": "the CATCH 18f2fc6d payload feeds response.error verbatim via the "
                          "#{catch.message} pill",
                "expected_catch_message": expect.get("catch_message"),
                "catch_payload": catch_payload,
            },
        ))

    return {"ok": _checks_ok(checks), "checks": checks}


# Verifier fragment for recipe 124203347 (/salesforce add bot command: OTM
# stand-in search {OpportunityId, TeamMemberRole 'RevOps BDE', UserId} +
# Opportunity search -> IF list_size==0 create OpportunityTeamMember +
# chat.update 'Added to <OppName>'; IF list_size==1 chat.update 'Current
# Opportunity Team Member on <OppName>'; list_size>=2 does NOTHING -- both
# IFs read the PRE-create search so at most one fires).
# To be merged into src/benchmark/verifier.py by the coordinating session.
# Uses only helpers already defined there: _verify_replay_recipe, _check.
#
# SEMANTIC TRAPS encoded via exact expects:
# - both slack posts carry advanced.ts = parameters.message_id, so the live
#   call is chat.update of the SEEDED message ts in the override channel
#   (channel C06USNHSQ6M is non-U -> override); the final text of that ONE
#   message is the observable and args.ts must equal the seeded ts byte-exact.
# - IF7 reads the PRE-create step-2 result: after the add branch created a
#   matching row, list_size is still 0 in step_outputs -- the create variant
#   must post 'Added to', never both texts.
# - the create writes through the stand-in field map (OpportunityId ->
#   OpportunityId__c etc.); the final snapshot must contain exactly
#   initial+1 owned OTM rows and the new row must read back the three
#   trigger values through the logical aliases.
# - list_size>=2 fires NEITHER IF: zero slack calls, zero creates (proves the
#   equals_to '1' pin is not '>=1').


def verify_124203347(result: dict[str, Any]) -> dict[str, Any]:
    replay = _verify_replay_recipe(result)
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") or {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    step_outputs = raw_execution.get("step_outputs") if isinstance(raw_execution.get("step_outputs"), dict) else {}
    trigger = details.get("trigger") if isinstance(details.get("trigger"), dict) else {}
    parameters = trigger.get("parameters") if isinstance(trigger.get("parameters"), dict) else {}
    seed_message = details.get("seed_slack_message") if isinstance(details.get("seed_slack_message"), dict) else {}
    checks = list(replay.get("checks") or [])

    def _otm_rows(snapshot: Any) -> list[dict[str, Any]]:
        salesforce = (snapshot or {}).get("salesforce") if isinstance(snapshot, dict) else {}
        return [
            row
            for row in (salesforce or {}).get("records") or []
            if isinstance(row, dict)
            and str(row.get("sobject") or "") == "OpportunityTeamMember"
            and not row.get("read_only")
        ]

    precheck = expect.get("otm_precheck_count")
    otm_search = step_outputs.get("3eb6ef17") if isinstance(step_outputs.get("3eb6ef17"), dict) else {}
    checks.append(_check(
        "otm_precheck_search_matches_expected_count",
        otm_search.get("list_size") == precheck,
        {
            "reason": "the step-2 search runs BEFORE any create and both IFs read this "
                      "immutable result; its list_size decides the whole branch shape",
            "expected_count": precheck,
            "actual_step_output_list_size": otm_search.get("list_size"),
        },
    ))

    opp_search = step_outputs.get("fbb7b395") if isinstance(step_outputs.get("fbb7b395"), dict) else {}
    opp_records = opp_search.get("records") if isinstance(opp_search.get("records"), list) else []
    opp_names = [
        str((row.get("fields") if isinstance(row.get("fields"), dict) else row).get("Name") or "")
        for row in opp_records
        if isinstance(row, dict)
    ]
    checks.append(_check(
        "opportunity_search_found_the_seeded_opportunity",
        opp_search.get("list_size") == 1
        and len(opp_names) == 1
        and bool(opp_names[0])
        and (expect.get("slack_text") is None or str(expect.get("slack_text")).endswith(opp_names[0])),
        {
            "reason": "step 3 resolves the announcement's '#{Opportunity Name}' pill from "
                      "the LIVE owned Opportunity (a missing record would render '' -- the "
                      "seeder forbids that)",
            "opp_names": opp_names,
            "expected_slack_text": expect.get("slack_text"),
        },
    ))

    create_rows = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == "salesforce.create_record"
    ]
    expected_fields = {
        "OpportunityId": str(parameters.get("opportunity_id") or ""),
        "TeamMemberRole": "RevOps BDE",
        "UserId": str(parameters.get("user_id") or ""),
    }
    if expect.get("created"):
        checks.append(_check(
            "create_wrote_trigger_values_through_the_stand_in",
            len(create_rows) == 1
            and (create_rows[0].get("args") or {}).get("sobject") == "OpportunityTeamMember"
            and (create_rows[0].get("args") or {}).get("fields") == expected_fields
            and bool(((create_rows[0].get("result") or {}).get("id") or "")),
            {
                "reason": "IF4 (list_size == 0) creates the OTM stand-in row with exactly the "
                          "three trigger-derived values; the live id proves the write landed",
                "expected_fields": expected_fields,
                "create_rows": create_rows,
            },
        ))
    else:
        checks.append(_check(
            "no_create_when_member_precheck_nonzero",
            not create_rows,
            {
                "reason": "IF4 fires only on list_size == 0; a create here means the compound "
                          "search filters did not bite",
                "create_rows": create_rows,
            },
        ))
    initial_otm = _otm_rows(details.get("initial_snapshot"))
    final_otm = _otm_rows(details.get("final_snapshot"))
    expected_final = len(initial_otm) + (1 if expect.get("created") else 0)
    new_rows = [
        row for row in final_otm
        if str(row.get("id") or "") not in {str(r.get("id") or "") for r in initial_otm}
    ]
    new_row_ok = True
    if expect.get("created"):
        new_fields = (new_rows[0].get("fields") if new_rows and isinstance(new_rows[0].get("fields"), dict) else {})
        new_row_ok = len(new_rows) == 1 and all(
            str(new_fields.get(key)) == value for key, value in expected_fields.items()
        )
    checks.append(_check(
        "final_snapshot_otm_rows_match_branch",
        len(final_otm) == expected_final and not (new_rows and not expect.get("created")) and new_row_ok,
        {
            "reason": "final owned OTM rows = seeded rows + exactly one created row on the "
                      "add branch; the new row must read back the trigger values through "
                      "the OpportunityId__c/UserId__c/TeamMemberRole__c logical aliases",
            "expected_final_count": expected_final,
            "initial_otm_ids": [row.get("id") for row in initial_otm],
            "final_otm": final_otm,
        },
    ))

    slack_rows = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == "slack.post_message"
    ]
    expected_text = expect.get("slack_text")
    if expected_text is None:
        checks.append(_check(
            "no_slack_post_when_neither_if_fires",
            not slack_rows,
            {
                "reason": "list_size >= 2 fails BOTH 'equals_to 0' and 'equals_to 1' -- the "
                          "seeded message must remain untouched",
                "slack_rows": slack_rows,
            },
        ))
    else:
        args = (slack_rows[0].get("args") or {}) if slack_rows else {}
        checks.append(_check(
            "single_chat_update_of_seeded_ts_with_exact_text",
            len(slack_rows) == 1
            and args.get("text") == expected_text
            and str(args.get("ts") or "") == str(seed_message.get("ts") or "")
            and bool(str(seed_message.get("ts") or ""))
            and args.get("channel") == seed_message.get("channel")
            and args.get("channel") == details.get("expected_channel")
            and str(slack_rows[0].get("as") or "") == ("73e80daa" if expect.get("created") else "ed5b9843"),
            {
                "reason": "exactly ONE of the two posts fires (both IFs read the pre-create "
                          "search); advanced.ts routes it to chat.update of the seeded "
                          "override-channel message, whose final text is the observable",
                "expected_text": expected_text,
                "expected_ts": seed_message.get("ts"),
                "expected_channel": details.get("expected_channel"),
                "slack_rows": slack_rows,
            },
        ))

    return {"ok": _checks_ok(checks), "checks": checks}


# Verifier fragment for recipe 120099421 (clock.scheduled_event every 7 days
# -> LIVE snowflake.run_custom_sql: applications_snapshot LEFT JOIN
# recipe_sophistication_app_tier ON title + entry_date=(current_date-1),
# WHERE category='app' AND app_tier IN 1..4 AND title NOT ILIKE '%secondary%'
# GROUP BY ALL -> lookup_table 3300543 search col2='app' -> IF rows.size !=
# entries.size -> FOREACH rows { search col1=title; IF 0 entries -> add_entry
# title/category/app_tier } -> unconditional top-level STOP).
# To be merged into src/benchmark/verifier.py by the coordinating session.
# Uses only helpers already defined there: _verify_replay_recipe, _check.
#
# SEMANTIC TRAPS encoded via exact expects:
# - The IF-4 comparison is SIZE-ONLY: variant_02 seeds equal counts with
#   DIFFERENT titles and nothing may sync (author blind spot pinned).
# - No ORDER BY: expect.sql_rows is capped at ONE row (seeder-enforced) so
#   the foreach trace stays deterministic; SQL-filter coverage rides on
#   decoys (category / tier-5 / %secondary% / wrong entry_date join-miss)
#   and GROUP BY ALL dedup — all carried by run_custom_sql result_count +
#   the exact sql_rows projection.
# - current_date is pinned via seed.snowflake_live.current_time; the args
#   SQL stays the VERBATIM raw text (rewrite happens inside the live client).
# - The top-level STOP always executes: every trace must end in the
#   aa772329 stopped:true row (exactly one stop row).
# - Snowflake is READ-ONLY here (snapshot equality + cleanup of BOTH seeded
#   tables); the lookup mock carries the only writes, pinned via
#   expect.final_lookup_rows (underscore bookkeeping keys stripped).


def verify_120099421(result: dict[str, Any]) -> dict[str, Any]:
    SQL_STEP = "39b44e18"
    BASELINE_STEP = "9f4b85c7"
    STOP_STEP = "aa772329"
    LOOKUP_TABLE = "3300543"
    SNAPSHOT_TABLE = "product.workato_usage.applications_snapshot"
    TIER_TABLE = "product.plg.recipe_sophistication_app_tier"
    base = _verify_replay_recipe(result)
    checks = list(base.get("checks") or [])
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") or {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    initial_snapshot = details.get("initial_snapshot") if isinstance(details.get("initial_snapshot"), dict) else {}
    final_snapshot = details.get("final_snapshot") if isinstance(details.get("final_snapshot"), dict) else {}

    required = ("sql_rows", "baseline_entry_count", "added_entries", "final_lookup_rows", "stopped")
    missing = [key for key in required if key not in expect]
    if missing:
        checks.append(_check(
            "expect_required_keys_missing",
            False,
            {
                "reason": "every 120099421 variant must pin sql_rows, "
                          "baseline_entry_count, added_entries, final_lookup_rows "
                          "and stopped",
                "missing_keys": missing,
                "expect": expect,
            },
        ))
        return {"ok": False, "checks": checks}

    sql_rows_expected = expect.get("sql_rows") if isinstance(expect.get("sql_rows"), list) else []
    baseline_expected = expect.get("baseline_entry_count")
    added_expected = expect.get("added_entries") if isinstance(expect.get("added_entries"), list) else []
    sizes_differ = len(sql_rows_expected) != baseline_expected

    sql_calls = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == "snowflake.run_custom_sql"
    ]
    projected = None
    if len(sql_calls) == 1:
        raw_rows = (sql_calls[0].get("result") or {}).get("rows")
        if isinstance(raw_rows, list):
            projected = [
                {
                    "title": row.get("title"),
                    "category": row.get("category"),
                    "app_tier": row.get("app_tier"),
                }
                for row in raw_rows
                if isinstance(row, dict)
            ]
    checks.append(_check(
        "sql_rows_match_exactly",
        projected == sql_rows_expected,
        {
            "reason": "exactly one live run_custom_sql whose result rows project "
                      "(lowercase aliases) to the pinned title/category/app_tier "
                      "rows — this carries the JOIN-date, category, tier-IN, "
                      "NOT-ILIKE and GROUP BY ALL groundtruth",
            "expected_rows": sql_rows_expected,
            "actual_projection": projected,
            "sql_calls": len(sql_calls),
        },
    ))

    baseline_calls = [
        row for row in trace
        if isinstance(row, dict)
        and row.get("tool") == "lookup_table.search_entries"
        and (row.get("args") or {}).get("parameters") == {"col2": "app"}
    ]
    baseline_entries = (baseline_calls[0].get("result") or {}).get("entries") if baseline_calls else None
    checks.append(_check(
        "baseline_search_matches",
        len(baseline_calls) == 1
        and str((baseline_calls[0].get("args") or {}).get("lookup_table_id")) == LOOKUP_TABLE
        and isinstance(baseline_entries, list)
        and len(baseline_entries) == baseline_expected,
        {
            "reason": "exactly one col2='app' baseline search against table 3300543 "
                      "returning the pinned entry count (the IF-4 rhs)",
            "expected_count": baseline_expected,
            "actual_calls": baseline_calls,
        },
    ))

    inner_calls = [
        row for row in trace
        if isinstance(row, dict)
        and row.get("tool") == "lookup_table.search_entries"
        and "col1" in ((row.get("args") or {}).get("parameters") or {})
    ]
    add_calls = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == "lookup_table.add_entry"
    ]
    if not sizes_differ:
        checks.append(_check(
            "equal_sizes_skip_foreach",
            not inner_calls and not add_calls,
            {
                "reason": "IF-4 compares SIZES only: equal counts must skip the "
                          "foreach entirely (even when titles differ — the pinned "
                          "author blind spot)",
                "inner_calls": inner_calls,
                "add_calls": add_calls,
            },
        ))
    else:
        expected_inner = [
            {"col1": row.get("title")} for row in sql_rows_expected if isinstance(row, dict)
        ]
        actual_inner = [
            (row.get("args") or {}).get("parameters") for row in inner_calls
        ]
        checks.append(_check(
            "foreach_inner_searches_match",
            actual_inner == expected_inner,
            {
                "reason": "one col1 search per SQL row, in row order (zero SQL rows "
                          "-> the foreach iterates zero times)",
                "expected_inner": expected_inner,
                "actual_inner": actual_inner,
            },
        ))
        actual_added = [
            (row.get("args") or {}).get("parameters") for row in add_calls
        ]
        checks.append(_check(
            "added_entries_match_exactly",
            actual_added == added_expected,
            {
                "reason": "add_entry fires exactly for SQL rows whose title is "
                          "missing from the lookup table, with the foreach pills "
                          "mapped col1/col2/col3 = title/category/app_tier",
                "expected_added": added_expected,
                "actual_added": actual_added,
            },
        ))

    final_rows_raw = (
        (final_snapshot.get("lookup_table") or {}).get("tables") or {}
    ).get(LOOKUP_TABLE)
    stripped = None
