def _case_field_126727318(row: dict[str, Any], field: str) -> Any:
    if field in row:
        return row[field]
    lower = str(field).lower()
    if lower in row:
        return row[lower]
    upper = str(field).upper()
    if upper in row:
        return row[upper]
    return None


