_LISTAGG_SET_COLUMNS_130550781 = {"BIZ_CRITICAL_APP_NAMES", "DISPLAY_OUTPUT_TOP_APPS"}


def _cell_matches_130550781(column: str, actual: Any, expected: Any) -> bool:
    if column in _LISTAGG_SET_COLUMNS_130550781:
        if not isinstance(actual, str) or not isinstance(expected, str):
            return actual == expected
        return sorted(part for part in actual.split(",")) == sorted(
            part for part in expected.split(",")
        )
    return actual == expected


