# SEMANTIC TRAPS encoded via exact expects:
# - the SQL is COMPOSED FROM PILLS: the lookup entry's col2 lands in the
#   SELECT alias position and parameters.type lands in the FROM clause
#   (salesforce.<type>, the registered 2-part seed table). args.sql must
#   equal expect.resolved_sql BYTE-EXACTLY and is re-derived here from the
#   traced get_entry result + the trigger (a stale expect cannot mask a
#   composition regression).
# - the raw SQL has NO ORDER BY: the connector's SEPARATE Order-by input
#   ('display_name') is appended by the engine -- args.sql must end with
#   ' ORDER BY display_name' and the raw limit '10000' rides along.
# - the bind is '%<typeahead.value>%' with CASE PRESERVED (lower() runs in
#   Snowflake on BOTH LIKE arms; display_name in the WHERE is a Snowflake
#   LATERAL column alias, triage-verified live).
# - menu options resolve via the HASH-SUFFIXED pills display_name_431ff3ca /
#   id_b497e547 (`_<8-hex>` strip + case-insensitive retry over the live row
#   keys): labels/values are recomputed from the ACTUAL live rows, exact
#   order (the appended ORDER BY pins it; seeds enforce distinct ASCII
#   display values), [] for zero matches.
# - catch branch: the forced error on 41c16eb0 raises BEFORE the live
#   adapter -> catch payload {type RawRecipeExecutionError, message} keyed
#   9e7ca880 -> STOP. The engine records only the bare stop marker
#   {number 6, stopped true} (stop_reason is never evaluated) and the stop
#   must be the LAST trace row -- generate_menu_options sits AFTER the try
#   and must never execute. The variant owns NO live state (empty snapshots,
#   no cleanup call).
# - happy runs are READ-ONLY on Snowflake: initial == final snapshot and
#   cleanup drops exactly the one registered 'salesforce.<type>' key.


def verify_91556848(result: dict[str, Any]) -> dict[str, Any]:
    LOOKUP_TABLE_ID = "355280"
    CATCH_STEP = "9e7ca880"
    replay = _verify_replay_recipe(result)
    checks = list(replay.get("checks") or [])
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") or {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    trigger = details.get("trigger") if isinstance(details.get("trigger"), dict) else {}
    parameters = trigger.get("parameters") if isinstance(trigger.get("parameters"), dict) else {}
    typeahead = trigger.get("typeahead") if isinstance(trigger.get("typeahead"), dict) else {}
    object_type = str(parameters.get("type") or "")
    initial_snapshot = details.get("initial_snapshot") if isinstance(details.get("initial_snapshot"), dict) else {}
    final_snapshot = details.get("final_snapshot") if isinstance(details.get("final_snapshot"), dict) else {}
    cleanup_response = (details.get("cleanup_response") or {}).get("snowflake_live")

    required = ("branch", "resolved_sql", "search_term", "menu_options", "stopped", "catch_message")
    missing = [key for key in required if key not in expect]
    if missing:
        checks.append(_check(
            "expect_required_keys_missing",
            False,
            {
                "reason": "every 91556848 variant must pin branch, resolved_sql, "
                          "search_term, menu_options, stopped and catch_message",
                "missing_keys": missing,
                "expect": expect,
            },
        ))
        return {"ok": False, "checks": checks}
    stopped = expect.get("stopped") is True

    lookup_rows = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == "lookup_table.get_entry"
    ]
    lookup_args = (lookup_rows[0].get("args") or {}) if lookup_rows else {}
    lookup_entry = ((lookup_rows[0].get("result") or {}).get("entry")) if lookup_rows else None
    checks.append(_check(
        "lookup_resolved_type_to_display_field",
        len(lookup_rows) == 1
        and lookup_args.get("lookup_table_id") == LOOKUP_TABLE_ID
        and lookup_args.get("parameters") == {"col1": object_type}
        and isinstance(lookup_entry, dict)
        and bool(str(lookup_entry.get("col2") or "")),
        {
            "reason": "get_entry matches '[SFBOT] Objects' on col1 == parameters.type; "
                      "the returned entry.col2 is the display field the SQL is composed "
                      "from (a null entry would compose invalid SQL -- never authored)",
            "expected_type": object_type,
            "lookup_rows": lookup_rows,
        },
    ))

    stop_rows = [row for row in trace if isinstance(row, dict) and row.get("stopped") is True]
    menu_rows = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == "slack_bot.generate_menu_options"
    ]
    sql_rows = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == "snowflake.search_rows_sql"
    ]
    checks.append(_check(
        "stop_outcome_matches_branch",
        bool(stop_rows) is stopped and bool(menu_rows) is not stopped,
        {
            "reason": "the stop lives INSIDE the catch: it fires exactly on the catch "
                      "branch and prevents step 7 (generate_menu_options sits AFTER "
                      "the try)",
            "expected_stopped": expect.get("stopped"),
            "stop_rows": stop_rows,
            "menu_rows": menu_rows,
        },
    ))

    if stopped:
        catch_payload = ((raw_execution.get("data") or {}).get("catch") or {}).get(CATCH_STEP)
        checks.append(_check(
            "catch_payload_matches_forced_error",
            isinstance(catch_payload, dict)
            and catch_payload.get("message") == expect.get("catch_message")
            and catch_payload.get("type") == "RawRecipeExecutionError"
            and bool(str(expect.get("catch_message") or "")),
            {
                "reason": "the forced error on 41c16eb0 raises BEFORE the live adapter; "
                          "the catch payload is keyed by the catch step id 9e7ca880",
                "expected_message": expect.get("catch_message"),
                "actual_catch_payload": catch_payload,
            },
        ))
        checks.append(_check(
            "stopped_exactly_at_step_6_bare_marker",
            not sql_rows
            and [(row.get("number"), row.get("keyword")) for row in stop_rows] == [(6, "stop")]
            and stop_rows[0].get("stop_reason") == expect.get("catch_message")
            and stop_rows[0].get("stop_with_error") is True
            and bool(trace) and trace[-1] is stop_rows[0],
            {
                "reason": "no snowflake call traces (the error fires pre-adapter); the "
                          "engine records the rendered catch message and error flag, "
                          "and nothing runs after it",
                "stop_rows": stop_rows,
                "sql_rows": sql_rows,
                "trace_tail": trace[-1] if trace else None,
            },
        ))
        checks.append(_check(
            "catch_branch_owns_no_live_state",
            initial_snapshot == {} and final_snapshot == {} and cleanup_response is None,
            {
                "reason": "catch variants seed no Snowflake table: empty snapshots and "
                          "no cleanup call",
                "initial_snapshot": initial_snapshot,
                "final_snapshot": final_snapshot,
                "cleanup_response": cleanup_response,
            },
        ))
        return {"ok": _checks_ok(checks), "checks": checks}

    sql_args = (sql_rows[0].get("args") or {}) if sql_rows else {}
    col2 = str((lookup_entry or {}).get("col2") or "") if isinstance(lookup_entry, dict) else ""
    derived_sql = (
        "select\n  " + col2 + " display_name,\n  id\nfrom salesforce." + object_type
        + "\nwhere lower(display_name) like lower(:search_term) ORDER BY display_name"
    )
    checks.append(_check(
        "composed_sql_matches_lookup_and_trigger_pills",
        len(sql_rows) == 1
        and sql_args.get("sql") == expect.get("resolved_sql")
        and sql_args.get("sql") == derived_sql
        and str(sql_args.get("sql") or "").endswith(" ORDER BY display_name")
        and sql_args.get("limit") == 10000,
        {
            "reason": "the SQL is composed from the get_entry col2 pill (SELECT alias) "
                      "+ the trigger type pill (FROM salesforce.<type>); the connector's "
                      "separate Order-by input is appended (the raw SQL has none) and "
                      "the raw limit '10000' passes through",
            "expected_resolved_sql": expect.get("resolved_sql"),
            "derived_sql": derived_sql,
            "actual_args": sql_args,
        },
    ))
    expected_term = "%" + str(typeahead.get("value") or "") + "%"
    checks.append(_check(
        "search_term_bind_preserves_case",
        sql_args.get("parameters") == {"search_term": expected_term}
        and expect.get("search_term") == expected_term,
        {
            "reason": "the bind is '%<typeahead.value>%' with case preserved -- lower() "
                      "runs in Snowflake on both LIKE arms, not in the engine",
            "expected_term": expected_term,
            "actual_parameters": sql_args.get("parameters"),
        },
    ))

    sql_result = (sql_rows[0].get("result") or {}) if sql_rows else {}
    returned = sql_result.get("rows") if isinstance(sql_result.get("rows"), list) else []
    derived_options = []
    for row in returned:
        if isinstance(row, dict):
            derived_options.append({
                "label": row.get("display_name", row.get("DISPLAY_NAME")),
                "value": row.get("id", row.get("ID")),
            })
    menu_args = (menu_rows[0].get("args") or {}) if menu_rows else {}
    menu_result = (menu_rows[0].get("result") or {}) if menu_rows else {}
    checks.append(_check(
        "menu_options_match_live_rows_exactly",
        menu_args.get("options") == expect.get("menu_options")
        and menu_result.get("options") == expect.get("menu_options")
        and derived_options == expect.get("menu_options"),
        {
            "reason": "one option per live row via ____source; label/value resolve the "
                      "HASH-SUFFIXED pills display_name_431ff3ca/id_b497e547 through the "
                      "`_<8-hex>` strip fallback over the live row keys; [] on zero rows",
            "expected_menu_options": expect.get("menu_options"),
            "derived_from_live_rows": derived_options,
            "actual_args": menu_args,
            "actual_result": menu_result,
        },
    ))
    labels = [
        str(option.get("label"))
        for option in (expect.get("menu_options") or [])
        if isinstance(option, dict)
    ]
    checks.append(_check(
        "menu_labels_strictly_ascending",
        all(earlier < later for earlier, later in zip(labels, labels[1:])),
        {
            "reason": "the appended ORDER BY display_name pins exact order; seeds "
                      "enforce distinct ASCII display values so codepoint order is the "
                      "live collation",
            "labels": labels,
        },
    ))

    initial_tables = (initial_snapshot.get("snowflake") or {}).get("tables")
    final_tables = (final_snapshot.get("snowflake") or {}).get("tables")
    checks.append(_check(
        "snowflake_backend_untouched_by_recipe",
        initial_tables is not None and initial_tables == final_tables,
        {
            "reason": "the recipe only SELECTs; the live snapshot must be identical "
                      "before and after the run",
            "initial_tables": initial_tables,
            "final_tables": final_tables,
        },
    ))
    checks.append(_check(
        "live_snowflake_seed_table_cleaned_up",
        isinstance(cleanup_response, dict)
        and bool(cleanup_response.get("ok"))
        and cleanup_response.get("dropped_tables") == ["salesforce." + object_type],
        {
            "reason": "cleanup must drop exactly the one registered 2-part table key",
            "expected_dropped": ["salesforce." + object_type],
            "cleanup_response": cleanup_response,
        },
    ))

    return {"ok": _checks_ok(checks), "checks": checks}


# Verifier fragment for recipe 88783356 (workato_service.receive_request
# 'Add person to Salesforce campaign' as d422758b -> TRY { LIVE
# salesforce.create_record CampaignMember {CampaignId <- request.campaign_id,
# Campaign_Member_Notes__c <- request.notes (MISSING pill drops the column),
# ContactId = starts_with?("003") ? id : skip, LeadId = starts_with?("00Q")
# ? id : skip, Status <- request.status} -> send_reply eae47ad6 success
# {campaign_member_id <- salesforce.25a6445f.id} } CATCH b3123d81 ->
# send_reply c764d8ca error {message <- catch.message}).
# Service->SF sibling of verify_88708198 (update; this one CREATES).
# To be merged into src/benchmark/verifier.py by the coordinating session.
# Uses only helpers already defined there: _verify_replay_recipe, _check.
#
# SEMANTIC TRAPS encoded via exact expects:
# - the SKIP-TERNARY PAIR splits ONE request field: a 003-id keeps ContactId
#   and DROPS LeadId, a 00Q-id the reverse, any other prefix drops BOTH (the
#   id never reaches Salesforce; the live org then rejects the memberless
#   create -> catch). create args.fields are compared EXACTLY (== on
#   expect.created_fields), so a leaked SKIP sentinel or a stray column
#   fails.
# - the success reply THREADS the live created id: reply.campaign_member_id
#   must equal the create result id (well-formed 00v... CampaignMember key
#   prefix) -- it is never a pinnable literal, expect carries __ANY__.
# - the catch reply forwards ONLY reply_type/reply/message; the raw node's
#   'code' 500 and 'custom_error_response' true are dropped by the adapter
#   (re-probed) -- their absence from args IS asserted. The message is LIVE
#   Salesforce error text: pinned as non-empty + equal to the catch payload,
#   never as an exact string. The failed create never traces (1 action).
# - live-state proof: success runs go 0 -> 1 owned CampaignMember whose live
#   read-back matches created_fields; the catch run keeps the snapshot
#   IDENTICAL (seeded Campaign untouched, no member); cleanup deletes ALL
#   owned records (the recipe-created member included) with zero leftovers.


def verify_88783356(result: dict[str, Any]) -> dict[str, Any]:
    SOBJECT = "CampaignMember"
    CATCH_STEP = "b3123d81"
    SUCCESS_REPLY = "eae47ad6"
    ERROR_REPLY = "c764d8ca"
    replay = _verify_replay_recipe(result)
    checks = list(replay.get("checks") or [])
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") or {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    initial_snapshot = details.get("initial_snapshot") if isinstance(details.get("initial_snapshot"), dict) else {}
    final_snapshot = details.get("final_snapshot") if isinstance(details.get("final_snapshot"), dict) else {}
    cleanup_response = (details.get("cleanup_response") or {}).get("salesforce")

    required = ("branch", "created_fields", "reply", "member_created")
    missing = [key for key in required if key not in expect]
    if missing:
        checks.append(_check(
            "expect_required_keys_missing",
            False,
            {
                "reason": "every 88783356 variant must pin branch, created_fields, "
                          "reply and member_created",
                "missing_keys": missing,
                "expect": expect,
            },
        ))
        return {"ok": False, "checks": checks}
    created = expect.get("member_created") is True

    def _member_rows(snapshot):
        salesforce = snapshot.get("salesforce") if isinstance(snapshot, dict) else {}
        return [
            row
            for row in (salesforce or {}).get("records") or []
            if isinstance(row, dict)
            and str(row.get("sobject") or "") == SOBJECT
            and not row.get("read_only")
        ]

    create_rows = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == "salesforce.create_record"
    ]
    reply_rows = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == "workato_service.send_reply"
    ]
    reply_args = (reply_rows[0].get("args") or {}) if reply_rows else {}
    checks.append(_check(
        "reply_step_matches_branch",
        len(reply_rows) == 1
        and str(reply_rows[0].get("as") or "") == (SUCCESS_REPLY if created else ERROR_REPLY),
        {
            "reason": "exactly one send_reply fires: the in-try success reply on the "
                      "create branches, the catch error reply otherwise",
            "expected_as": SUCCESS_REPLY if created else ERROR_REPLY,
            "reply_rows": reply_rows,
        },
    ))
    checks.append(_check(
        "reply_forwards_only_reply_type_reply_message",
        set(reply_args) <= {"reply_type", "reply", "message"}
        and "code" not in reply_args
        and "custom_error_response" not in reply_args,
        {
            "reason": "the send_reply adapter forwards reply_type/reply/message only; "
                      "the raw error node's 'code' 500 and 'custom_error_response' true "
                      "must never surface in args",
            "actual_args": reply_args,
        },
    ))

    initial_members = _member_rows(initial_snapshot)
    final_members = _member_rows(final_snapshot)

    if created:
        create_args = (create_rows[0].get("args") or {}) if create_rows else {}
        create_result = (create_rows[0].get("result") or {}) if create_rows else {}
        created_id = str(create_result.get("id") or "")
        checks.append(_check(
            "create_args_match_derived_fields_exactly",
            len(create_rows) == 1
            and create_args.get("sobject") == SOBJECT
            and create_args.get("fields") == expect.get("created_fields")
            and isinstance(expect.get("created_fields"), dict),
            {
                "reason": "fields must carry EXACTLY the ternary-derived set: the kept "
                          "Contact/Lead arm, CampaignId, Status, and the notes column "
                          "only when the request sent notes (a MISSING pill drops it); "
                          "the skipped arm must be ABSENT, not null",
                "expected_fields": expect.get("created_fields"),
                "create_rows": create_rows,
            },
        ))
        import re as _re
        checks.append(_check(
            "success_reply_threads_live_created_id",
            bool(_re.fullmatch(r"00[vV][a-zA-Z0-9]{12}(?:[a-zA-Z0-9]{3})?", created_id))
            and reply_args.get("reply_type") == "success"
            and reply_args.get("reply") == {"campaign_member_id": created_id},
            {
                "reason": "reply.campaign_member_id is the salesforce.25a6445f.id pill: "
                          "it must equal the LIVE create result id (00v key prefix), "
                          "never a seed literal",
                "created_id": created_id,
                "reply_args": reply_args,
            },
        ))
        new_members = [
            row for row in final_members
            if str(row.get("id") or "") not in {str(r.get("id") or "") for r in initial_members}
        ]
        new_fields = (new_members[0].get("fields") if new_members and isinstance(new_members[0].get("fields"), dict) else {})
        expected_fields = expect.get("created_fields") if isinstance(expect.get("created_fields"), dict) else {}
        checks.append(_check(
            "live_member_created_and_reads_back",
            len(initial_members) == 0
            and len(final_members) == 1
            and len(new_members) == 1
            and str(new_members[0].get("id") or "") == created_id
            and all(str(new_fields.get(key)) == str(value) for key, value in expected_fields.items()),
            {
                "reason": "exactly one owned CampaignMember exists after the run (none "
                          "before) and its live read-back carries every created field "
                          "value",
                "expected_fields": expected_fields,
                "initial_members": initial_members,
                "final_members": final_members,
            },
        ))
    else:
        catch_payload = ((raw_execution.get("data") or {}).get("catch") or {}).get(CATCH_STEP)
        message = (catch_payload or {}).get("message") if isinstance(catch_payload, dict) else None
        checks.append(_check(
            "failed_create_never_traces",
            not create_rows,
            {
                "reason": "the live rejection raises inside the create adapter, so no "
                          "salesforce.create_record row traces (1 executed action)",
                "create_rows": create_rows,
            },
        ))
        checks.append(_check(
            "error_reply_echoes_live_catch_message",
            isinstance(message, str)
            and bool(message.strip())
            and reply_args.get("reply_type") == "error"
            and reply_args.get("reply") == {}
            and reply_args.get("message") == message,
            {
                "reason": "the catch payload message is LIVE Salesforce error text "
                          "(never pinned verbatim); the error reply must echo it exactly",
                "catch_payload": catch_payload,
                "reply_args": reply_args,
            },
        ))
        initial_records = (initial_snapshot.get("salesforce") or {}).get("records")
        final_records = (final_snapshot.get("salesforce") or {}).get("records")
        checks.append(_check(
            "seeded_campaign_untouched_and_no_member",
            initial_records is not None
            and initial_records == final_records
            and not final_members,
            {
                "reason": "the rejected create left nothing behind: snapshots identical, "
                          "zero CampaignMember rows",
                "initial_records": initial_records,
                "final_records": final_records,
            },
        ))

    checks.append(_check(
        "live_salesforce_cleanup_left_zero_records",
        isinstance(cleanup_response, dict)
        and bool(cleanup_response.get("ok"))
        and cleanup_response.get("leftovers") == [],
        {
            "reason": "cleanup deletes ALL owned records -- the seeded Campaign/"
                      "Contact/Lead and the recipe-created CampaignMember (registered "
                      "as owned at create time) -- with zero leftovers",
            "cleanup_response": cleanup_response,
        },
    ))

    return {"ok": _checks_ok(checks), "checks": checks}


