# Verifier fragment for recipe 91033108 (slack_bot.new_event
# member_left_channel eb16353c -> lookup_table.search_entries f9501965 table
# 3357221 config {col2: channel} -> IF size==0 STOP 4 (non-error, bare
# marker) -> lookup_table.search_entries 902801c9 table 3357223 schedule
# {col2: user AND col3: channel} -> lookup_table.delete_entry c0945c6f table
# 3357223 id = entries[current_item].id, ignore_not_found 'false'). All
# backends Workato-internal mocks (lookup tables + seeded trigger event).
#
# NEW verify_91033108 — to be merged into src/benchmark/verifier.py by the
# coordinating session. Uses only helpers already defined there:
# _verify_replay_recipe, _check.
#
# SEMANTIC TRAPS encoded via exact expects (variant input.json):
# - FIRST-MATCH delete: the delete id pill is entries[current_item].id
#   OUTSIDE any foreach = the FIRST schedule row matching user+channel; the
#   fragment recomputes the match from the INITIAL snapshot + the seeded
#   trigger and requires args.id == expect.deleted_entry_id == first match,
#   every OTHER matching row still present in the final table (a
#   delete-all-matches implementation fails here), and the deleted id absent.
# - AND-match: rows sharing only the user (different channel) or only the
#   channel (different user) must survive — pinned via the byte-exact
#   final_table_rows and the delete-scope check.
# - stop semantics: the stop trace row is the bare marker {number: 4,
#   keyword: 'stop', stopped: true} (stop_with_error is never evaluated, the
#   node carries NO as-id); stopped variants pin the marker as the LAST
#   trace row and exactly one search tool call.
# - ignore_not_found stays the literal STRING 'false' in the delete args
#   (toggleCfg custom value) and the mock reports deleted: true.
# - byte-exact initial/final_table_rows for BOTH tables (incl.
#   _row_id/_created_by bookkeeping); the config table 3357221 must be
#   identical before/after on every branch (ghost writes fail).
# - UNGUARDED EDGE (documented, never seeded): config present + zero
#   matching schedule rows is a catchless job error (engine NonRecipeError
#   'lookup_table.delete_entry requires a resolved entry id') — the seeder
#   refuses such seeds, so the verifier never sees that path.


def verify_91033108(result: dict[str, Any]) -> dict[str, Any]:
    CONFIG_TABLE = "3357221"
    SCHED_TABLE = "3357223"
    STOP_NUMBER = 4
    replay = _verify_replay_recipe(result)
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") if isinstance(details.get("raw_execution"), dict) else {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    tool_calls = result.get("tool_calls") or []
    trigger = details.get("trigger") if isinstance(details.get("trigger"), dict) else {}
    event = trigger.get("member_left_channel") if isinstance(trigger.get("member_left_channel"), dict) else {}
    initial_snapshot = details.get("initial_snapshot") if isinstance(details.get("initial_snapshot"), dict) else {}
    final_snapshot = details.get("final_snapshot") if isinstance(details.get("final_snapshot"), dict) else {}
    checks = list(replay.get("checks") or [])

    required_keys = (
        "executed_action_count",
        "tools",
        "tool_expectations",
        "branch",
        "stopped",
        "deleted_entry_id",
        "initial_table_rows",
        "final_table_rows",
    )
    missing = [key for key in required_keys if key not in expect]
    if missing:
        checks.append(_check(
            "expect_required_keys_missing",
            False,
            {"reason": f"every 91033108 variant must pin {missing}", "expect": expect},
        ))
        return {"ok": False, "checks": checks}

    branch = expect.get("branch")
    checks.append(_check(
        "expect_branch_is_known",
        branch in ("config_missing_stop", "schedule_delete_first"),
        {"branch": branch},
    ))

    # Stop semantics: only the missing-config branch reaches the STOP; the
    # The marker has no as-id, but still records the canonical empty reason
    # and false error flag.
    stop_rows = [row for row in trace if isinstance(row, dict) and row.get("stopped") is True]
    checks.append(_check(
        "stop_outcome_matches_expected",
        bool(stop_rows) is bool(expect.get("stopped")),
        {"expected_stopped": expect.get("stopped"), "stop_rows": stop_rows},
    ))
    if expect.get("stopped"):
        checks.append(_check(
            "stopped_exactly_at_step_4_bare_marker",
            (
                [(row.get("number"), row.get("keyword")) for row in stop_rows]
                == [(STOP_NUMBER, "stop")]
                and stop_rows[0].get("stop_reason") == ""
                and stop_rows[0].get("stop_with_error") is False
                and trace
                and trace[-1] is stop_rows[0]
            ),
            {"stop_rows": stop_rows, "trace_tail": trace[-1] if trace else None},
        ))
        checks.append(_check(
            "stopped_run_called_only_the_config_search",
            [call.get("tool") for call in tool_calls] == ["lookup_table.search_entries"],
            {"tool_calls": [call.get("tool") for call in tool_calls]},
        ))

    if branch == "schedule_delete_first":
        user = str(event.get("user") or "")
        channel = str(event.get("channel") or "")
        initial_sched = _91033108_rows(initial_snapshot, SCHED_TABLE)
        final_sched = _91033108_rows(final_snapshot, SCHED_TABLE)
        matching = [
            row for row in initial_sched
            if str(row.get("col2")) == user and str(row.get("col3")) == channel
        ]
        delete_calls = [call for call in tool_calls if call.get("tool") == "lookup_table.delete_entry"]
        delete_args = (delete_calls[0].get("args") or {}) if delete_calls else {}
        delete_result = (delete_calls[0].get("result") or {}) if delete_calls else {}
        checks.append(_check(
            "delete_targeted_first_matching_schedule_row",
            (
                len(delete_calls) == 1
                and bool(matching)
                and delete_args.get("id") == matching[0].get("id")
                and delete_args.get("id") == expect.get("deleted_entry_id")
                and str(delete_args.get("lookup_table_id")) == SCHED_TABLE
            ),
            {
                "reason": "entries[current_item].id outside any foreach = FIRST user+channel "
                          "match; deleting a later match or all matches fails",
                "expected_deleted_entry_id": expect.get("deleted_entry_id"),
                "matching_rows": matching,
                "delete_calls": delete_calls,
            },
        ))
        checks.append(_check(
            "delete_kept_verbatim_ignore_not_found_and_deleted",
            delete_args.get("ignore_not_found") == "false" and delete_result.get("deleted") is True,
            {"delete_args": delete_args, "delete_result": delete_result},
        ))
        deleted_id = str(expect.get("deleted_entry_id"))
        survivors = [row for row in matching[1:]] if matching else []
        checks.append(_check(
            "only_the_first_match_was_deleted",
            (
                all(any(str(row.get("id")) == str(surv.get("id")) for row in final_sched) for surv in survivors)
                and not any(str(row.get("id")) == deleted_id for row in final_sched)
                and len(final_sched) == len(initial_sched) - 1
            ),
            {
                "reason": "other rows matching the SAME user+channel must survive (first-match "
                          "delete), as must same-user-other-channel and other-user rows",
                "deleted_id": deleted_id,
                "surviving_matches_expected": survivors,
                "final_schedule_rows": final_sched,
            },
        ))

    # Byte-exact mock-table state transition for BOTH tables (incl.
    # _row_id/_created_by bookkeeping); config table never mutates.
    for label, snapshot in (("initial", initial_snapshot), ("final", final_snapshot)):
        expected_tables = expect.get(f"{label}_table_rows")
        actual_tables = ((snapshot.get("lookup_table") or {}).get("tables") or {})
        actual_trimmed = {
            table_id: actual_tables.get(table_id)
            for table_id in (CONFIG_TABLE, SCHED_TABLE)
        }
        checks.append(_check(
            f"{label}_table_rows_match_exactly",
            isinstance(expected_tables, dict) and actual_trimmed == expected_tables,
            {"expected": expected_tables, "actual": actual_trimmed},
        ))
    checks.append(_check(
        "config_table_untouched",
        (
            ((initial_snapshot.get("lookup_table") or {}).get("tables") or {}).get(CONFIG_TABLE)
            == ((final_snapshot.get("lookup_table") or {}).get("tables") or {}).get(CONFIG_TABLE)
        ),
        {
            "initial": ((initial_snapshot.get("lookup_table") or {}).get("tables") or {}).get(CONFIG_TABLE),
            "final": ((final_snapshot.get("lookup_table") or {}).get("tables") or {}).get(CONFIG_TABLE),
        },
    ))

    # Table-targeting guard: every lookup call must hit this recipe's tables.
    bad_targets = [
        call for call in tool_calls
        if str(call.get("tool") or "").startswith("lookup_table.")
        and str((call.get("args") or {}).get("lookup_table_id")) not in (CONFIG_TABLE, SCHED_TABLE)
    ]
    checks.append(_check(
        "lookup_calls_target_only_recipe_tables",
        not bad_targets,
        {"bad_targets": bad_targets},
    ))

    return {"ok": _checks_ok(checks), "checks": checks}


def _91033108_rows(snapshot: dict[str, Any], table_id: str) -> list[dict[str, Any]]:
    rows = ((snapshot.get("lookup_table") or {}).get("tables") or {}).get(table_id) or []
    return [row for row in rows if isinstance(row, dict)]


