    return_args = (return_rows[0].get("args") or {}) if return_rows else {}
    actual_result = return_args.get("result") if isinstance(return_args.get("result"), dict) else {}
    expected_result = expect.get("return_result") if isinstance(expect.get("return_result"), dict) else {}
