    missing = [key for key in required if key not in expect]
    if missing:
        checks.append(_check(
            "expect_required_keys_missing",
            False,
            {
                "reason": "every 116340422 variant must pin trace_tools, the declared "
                          "variables and the exact 200 response object",
                "missing_keys": missing,
                "expect": expect,
            },
        ))
        return {"ok": False, "checks": checks}

    trace_tools = [
        row.get("tool")
        for row in trace
        if isinstance(row, dict) and row.get("keyword") == "action" and row.get("tool")
    ]
    checks.append(_check(
        "trace_action_sequence_matches",
        trace_tools == EXPECTED_TRACE
        and expect.get("trace_tools") == EXPECTED_TRACE
        and bool(trace)
        and (trace[-1] or {}).get("tool") == "workato_api_platform.return_response",
        {
            "reason": "linear body ending in the TERMINAL return_response — nothing "
                      "may trace after it",
            "expected_trace": EXPECTED_TRACE,
            "actual_trace": trace_tools,
            "last_row": trace[-1] if trace else None,
        },
    ))

    declare_rows = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == "workato_runtime.declare_variable"
    ]
    declare_result = (declare_rows[0].get("result") or {}) if declare_rows else {}
    checks.append(_check(
        "declared_variables_match",
        len(declare_rows) == 1 and declare_result == expect.get("declared"),
        {
            "reason": "||-defaults + declared-int coercion + the LIKE-vs-1=1 ternary "
                      "are the recipe's only branch layer — pinned exactly",
            "expected": expect.get("declared"),
            "declare_result": declare_result,
        },
    ))

    expected_response = expect.get("response") if isinstance(expect.get("response"), dict) else {}
    checks.append(_check(
        "return_value_matches_expected_response_exactly",
        raw_execution.get("return_value") == expected_response,
        {
            "reason": "ordered result rows (hash-suffix pill derefs, int ids) + int "
                      "total (count(1) is 0 on zero matches, never a falsy render)",
            "expected_response": expected_response,
            "return_value": raw_execution.get("return_value"),
        },
    ))

    count_calls = [
        call for call in tool_calls
        if call.get("tool") == "snowflake.search_rows_sql"
    ]
    count_args = (count_calls[1].get("args") or {}) if len(count_calls) > 1 else {}
    count_result = (count_calls[1].get("result") or {}) if len(count_calls) > 1 else {}
    count_rows = count_result.get("rows") if isinstance(count_result.get("rows"), list) else []
    total = expected_response.get("total")
    checks.append(_check(
        "count_query_unpaginated_single_row",
        len(count_calls) == 2
        and count_args.get("limit") is None
        and count_args.get("offset") is None
        and len(count_rows) == 1
        and any(value == total for key, value in (count_rows[0] or {}).items() if str(key).lower() == "row_count"),
        {
            "reason": "the count arm shares the WHERE branch but never the "
                      "pagination — total is the UNSLICED match count",
            "count_args": count_args,
            "count_rows": count_rows,
            "expected_total": total,
        },
    ))

    initial_rows = ((details.get("initial_snapshot") or {}).get("snowflake") or {}).get("tables", {}).get(TABLE_KEY)
    final_rows = ((details.get("final_snapshot") or {}).get("snowflake") or {}).get("tables", {}).get(TABLE_KEY)
    checks.append(_check(
        "snowflake_read_only",
        isinstance(initial_rows, list) and initial_rows == final_rows,
        {"initial_rows": initial_rows, "final_rows": final_rows},
    ))

    cleanup = ((details.get("cleanup_response") or {}).get("snowflake_live") or {})
    checks.append(_check(
        "snowflake_cleanup_dropped_table",
        cleanup.get("ok") is True and TABLE_KEY in (cleanup.get("dropped_tables") or []),
        {"cleanup": cleanup},
    ))
    return {"ok": _checks_ok(checks), "checks": checks}

