def _multiset_105192491(rows: Any) -> list[str]:
    import json as _json

    out: list[str] = []
    for row in rows if isinstance(rows, list) else []:
        if not isinstance(row, dict):
            out.append(_json.dumps(row, default=str))
            continue
        public = {
            str(key): value
            for key, value in row.items()
            if not str(key).startswith("_")
        }
        out.append(_json.dumps(public, sort_keys=True, default=str))
    return sorted(out)


def _qualifying_from_snapshot_105192491(
    initial_sf: dict[str, Any],
) -> list[dict[str, Any]] | None:
    """Re-derive the final SELECT from the live pre-run snapshot of all 6
    seeded tables (faithful CTE walk). Returns None when the snapshot is
    unusable."""
    import json as _json

    tables: dict[str, list[dict[str, Any]]] = {}
    for name in _SEED_TABLES_105192491:
        rows = initial_sf.get(name)
        if not isinstance(rows, list) or not all(isinstance(row, dict) for row in rows):
            return None
        tables[name] = rows
    # distinct_lookup_table_entries: SELECT DISTINCT * collapse
    entries = [
        _json.loads(text)
        for text in sorted(
            {
                _json.dumps(
                    {
                        "lookup_table_id": str(row.get("lookup_table_id")),
                        "data_center": str(row.get("data_center")),
                        "data_size_bytes": int(row.get("data_size_bytes") or 0),
                    },
                    sort_keys=True,
                )
                for row in tables[_ENTRIES_TABLE_105192491]
            }
        )
    ]
    # lut_stats: entries JOIN lut JOIN workspace(is_latest) JOIN
    # account(is_latest), COUNT per 9-key group
    stats: dict[tuple[str, ...], int] = {}
    for lut in tables[_LUTS_TABLE_105192491]:
        matching_entries = [
            entry
            for entry in entries
            if entry["lookup_table_id"] == str(lut.get("id"))
            and entry["data_center"] == str(lut.get("data_center"))
        ]
        workspaces = [
            wd
            for wd in tables[_WORKSPACE_TABLE_105192491]
            if str(wd.get("workspace_id")) == str(lut.get("user_id"))
            and str(wd.get("data_center")) == str(lut.get("data_center"))
            and wd.get("is_latest") is True
        ]
        for entry in matching_entries:
            for wd in workspaces:
                for ad in tables[_ACCOUNTS_TABLE_105192491]:
                    if (
                        str(ad.get("account_id")) != str(wd.get("sales_account_id"))
                        or ad.get("is_latest") is not True
                    ):
                        continue
                    key = (
                        str(wd.get("data_center")),
                        str(wd.get("workspace_id")),
                        str(wd.get("workspace_name")),
                        str(wd.get("environment")),
                        str(ad.get("account_name")),
                        str(ad.get("owner")),
                        str(ad.get("success_owner")),
                        str(lut.get("id")),
                        str(lut.get("name")),
                    )
                    stats[key] = stats.get(key, 0) + 1
    # lut_analysis existence join + final DISTINCT/WHERE
    final: set[tuple[str, str, int]] = set()
    for key, total_rows in stats.items():
        data_center, lut_id, lut_name = key[0], key[7], key[8]
        has_partner = any(
            str(ls.get("object_name")) == lut_id
            and str(ls.get("data_center")) == data_center
            and any(
                str(rd.get("flow_id")) == str(ls.get("flow_id"))
                and str(rd.get("data_center")) == data_center
                and rd.get("is_latest") is True
                for rd in tables[_RECIPE_DIM_TABLE_105192491]
            )
            for ls in tables[_LINE_STATS_TABLE_105192491]
        )
        if not has_partner:
            continue
        if data_center != "US" or lut_id not in _IN_LIST_105192491:
            continue
        final.add((lut_id, lut_name, int(total_rows)))
    return [
        {"lut_id": lut_id, "lut_name": lut_name, "total_rows": total_rows}
        for lut_id, lut_name, total_rows in sorted(final)
    ]


def verify_105192491(result: dict[str, Any]) -> dict[str, Any]:
    SQL_STEP = "b9f9415a"
    ADD_STEP = "1f3cbcf0"
    replay = _verify_replay_recipe(result)
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") if isinstance(details.get("raw_execution"), dict) else {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    initial_snapshot = details.get("initial_snapshot") if isinstance(details.get("initial_snapshot"), dict) else {}
    final_snapshot = details.get("final_snapshot") if isinstance(details.get("final_snapshot"), dict) else {}
    cleanup_response = (details.get("cleanup_response") or {}).get("snowflake_live") or {}
    checks = list(replay.get("checks") or [])

    required = (
        "snapshot_date",
        "sql_row_count",
        "sql_rows",
        "added_records",
        "final_row_count",
        "final_table_rows",
    )
    missing = [key for key in required if key not in expect]
    if missing:
        checks.append(_check(
            "expect_required_keys_missing",
            False,
            {"reason": f"every 105192491 variant must pin {missing}", "expect": expect},
        ))
        return {"ok": False, "checks": checks}

    action_rows = [row for row in trace if isinstance(row, dict) and row.get("tool")]
    by_as: dict[str, list[dict[str, Any]]] = {}
    for row in action_rows:
        by_as.setdefault(str(row.get("as") or ""), []).append(row)

    # --- live SELECT: count + (lut_id, lut_name, total_rows) multiset ---
    sql_rows = by_as.get(SQL_STEP) or []
    sql_result = (sql_rows[0].get("result") or {}) if sql_rows else {}
    returned_rows = sql_result.get("rows") if isinstance(sql_result.get("rows"), list) else []
    mapped_returned = [
        {
            "lut_id": str((row or {}).get("lut_id")),
            "lut_name": str((row or {}).get("lut_name")),
            "total_rows": (row or {}).get("total_rows"),
        }
        for row in returned_rows
        if isinstance(row, dict)
    ]
    checks.append(_check(
        "select_row_count_and_multiset_match",
        len(sql_rows) == 1
        and len(returned_rows) == expect.get("sql_row_count")
        and _multiset_105192491(mapped_returned) == _multiset_105192491(expect.get("sql_rows")),
        {
            "expected_row_count": expect.get("sql_row_count"),
            "expected_rows": expect.get("sql_rows"),
            "actual_rows_mapped": mapped_returned,
        },
    ))

    # --- LIVE-GROUNDED CTE RECONSTRUCTION from the pre-run snapshot ---
    initial_sf = (initial_snapshot.get("snowflake") or {}).get("tables", {})
    derived = _qualifying_from_snapshot_105192491(initial_sf if isinstance(initial_sf, dict) else {})
    checks.append(_check(
        "select_rows_match_snapshot_derived_qualifying_set",
        derived is not None
        and _multiset_105192491(mapped_returned) == _multiset_105192491(derived),
        {
            "reason": "distinct-entry collapse + is_latest joins + COUNT + "
                      "line_stats/recipe_dim existence + US/IN-list filter, "
                      "re-derived from the live pre-run snapshot",
            "derived_qualifying": derived,
            "actual_rows_mapped": mapped_returned,
        },
    ))

    # --- foreach fan-out: one add_record per SELECT row, records pinned as
    # a multiset (call order is live SELECT order -- unpinned), every date
    # column equals the pinned SG snapshot date ---
    add_rows = by_as.get(ADD_STEP) or []
    add_records = [
        (row.get("args") or {}).get("record") or {} for row in add_rows
    ]
    checks.append(_check(
        "add_record_calls_match_expected_multiset",
        len(add_rows) == expect.get("sql_row_count")
        and all(row.get("tool") == "workato_db_table.add_record" for row in add_rows)
        and all(
            str((row.get("args") or {}).get("table_id") or "") == _DB_TABLE_105192491
            for row in add_rows
        )
        and _multiset_105192491(add_records) == _multiset_105192491(expect.get("added_records")),
        {
            "expected_records": expect.get("added_records"),
            "actual_records": add_records,
        },
    ))
    checks.append(_check(
        "every_added_record_carries_pinned_sg_snapshot_date",
        all(
            str(record.get(_DATE_COL_105192491)) == str(expect.get("snapshot_date"))
            for record in add_records
        ),
        {
            "reason": "=job_created_at.in_time_zone('Asia/Singapore').to_date -- "
                      "SG conversion can roll the date past the UTC instant",
            "expected_snapshot_date": expect.get("snapshot_date"),
            "actual_records": add_records,
        },
    ))

    # --- final db table: pre-seeded rows + appended snapshots (multiset) ---
    final_rows = (
        (final_snapshot.get("workato_db_table") or {}).get("tables", {}).get(_DB_TABLE_105192491, [])
    )
    checks.append(_check(
        "final_db_table_matches_expected_multiset",
        len(final_rows) == expect.get("final_row_count")
        and _multiset_105192491(final_rows)
        == _multiset_105192491(expect.get("final_table_rows")),
        {
            "reason": "add_record APPENDS (no truncate): final = pre-seed + adds",
            "expected_row_count": expect.get("final_row_count"),
            "expected_rows": expect.get("final_table_rows"),
            "actual_rows": final_rows,
        },
    ))

    # --- Snowflake is READ-ONLY here: all 6 live tables unchanged ---
    final_sf = (final_snapshot.get("snowflake") or {}).get("tables", {})
    checks.append(_check(
        "snowflake_snapshot_unchanged",
        isinstance(initial_sf, dict)
        and sorted(initial_sf) == sorted(_SEED_TABLES_105192491)
        and initial_sf == final_sf,
        {"initial_tables": initial_sf, "final_tables": final_sf},
    ))

    # --- cleanup dropped exactly the 6 seeded live tables ---
    checks.append(_check(
        "snowflake_cleanup_dropped_seeded_tables",
        bool(cleanup_response.get("ok"))
        and sorted(cleanup_response.get("dropped_tables") or [])
        == sorted(_SEED_TABLES_105192491),
        {"cleanup_response": cleanup_response},
    ))
    return {"ok": _checks_ok(checks), "checks": checks}

