def verify_125838852(result: dict[str, Any]) -> dict[str, Any]:
    replay = _verify_replay_recipe(result)
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") or {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    checks = list(replay.get("checks") or [])

    required = (
        "case",
        "executed_action_count",
        "tools",
        "tool_expectations",
        "menu_options",
        "empty_reason",
        "decoy_accounts",
    )
    missing = [key for key in required if key not in expect]
    if missing:
        checks.append(_check(
            "expect_required_keys_missing",
            False,
            {"reason": f"every 125838852 variant must pin {missing}", "expect": expect},
        ))
        return {"ok": False, "checks": checks}

    search_rows = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == "salesforce.search_records"
    ]
    search_results = [(row.get("result") or {}).get("records") for row in search_rows]
    checks.append(_check(
        "dead_query_returned_zero_records",
        search_results == [[]],
        {
            "reason": "the foreign RecordTypeId equality never matches a live record: "
                      "exactly one search, exactly zero records",
            "actual_search_results": search_results,
        },
    ))

    trigger = details.get("trigger") if isinstance(details.get("trigger"), dict) else {}
    typeahead_obj = trigger.get("typeahead") if isinstance(trigger.get("typeahead"), dict) else {}
    typeahead = str(typeahead_obj.get("value") or "")
    expected_query = (
        "NAME LIKE '%" + typeahead + "%' AND RecordTypeId = '" + _FOREIGN_RT_125838852 + "'"
    )
    search_args = (search_rows[0].get("args") or {}) if search_rows else {}
    checks.append(_check(
        "resolved_query_recomputed_from_trigger",
        bool(typeahead)
        and str(search_args.get("query") or "") == expected_query
        and str(search_args.get("sobject") or "") == "Account"
        and str(search_args.get("limit") or "") == "150",
        {
            "reason": "the only dereferenced trigger field (typeahead.value) is "
                      "interpolated verbatim between the LIKE quotes ahead of the "
                      "foreign RT equality; recomputed here so the args pin cannot "
                      "drift from the payload",
            "typeahead": typeahead,
            "expected_query": expected_query,
            "actual_args": search_args,
        },
    ))

    menu_rows = [
        row for row in trace
        if isinstance(row, dict) and row.get("tool") == "slack_bot.generate_menu_options"
    ]
    menu_args_options = [(row.get("args") or {}).get("options") for row in menu_rows]
    menu_result_options = [(row.get("result") or {}).get("options") for row in menu_rows]
    checks.append(_check(
        "menu_rendered_empty_exactly",
        menu_args_options == [[]]
        and menu_result_options == [[]]
        and expect.get("menu_options") == [],
        {
            "reason": "the ____source list is the always-empty search result, so the "
                      "terminal observable is exactly one generate_menu_options call "
                      "with options [] (the >0-options branch is org-unreachable and "
                      "documented, not forced)",
            "actual_args_options": menu_args_options,
            "actual_result_options": menu_result_options,
            "expected_menu_options": expect.get("menu_options"),
        },
    ))

    # Dead-branch attestation: each pinned decoy must appear in the initial
    # snapshot with a live read-back whose REAL RecordTypeId differs from the
    # recipe's foreign literal, and whose declared LIKE-arm flag matches the
    # recomputed containment against the trigger typeahead.
    snapshot_records = (
        ((details.get("initial_snapshot") or {}).get("salesforce") or {}).get("records") or []
    )
    accounts_by_name: dict[str, dict[str, Any]] = {}
    for row in snapshot_records:
        if not isinstance(row, dict) or str(row.get("sobject") or "") != "Account":
            continue
        fields = row.get("fields") if isinstance(row.get("fields"), dict) else {}
        accounts_by_name[str(fields.get("Name") or "")] = fields
    expected_decoys = expect.get("decoy_accounts") if isinstance(expect.get("decoy_accounts"), list) else []
    matched = []
    any_name_match = False
    for decoy in expected_decoys:
        if not isinstance(decoy, dict):
            matched.append({"decoy": decoy, "ok": False})
            continue
        name = str(decoy.get("Name") or "")
        declared = decoy.get("name_matches_typeahead")
        fields = accounts_by_name.get(name)
        recomputed = bool(typeahead) and typeahead.lower() in name.lower()
        ok = (
            isinstance(fields, dict)
            and "RecordTypeId" in fields
            and str(fields.get("RecordTypeId") or "") != _FOREIGN_RT_125838852
            and isinstance(declared, bool)
            and declared == recomputed
        )
        any_name_match = any_name_match or recomputed
        matched.append({
            "decoy": decoy,
            "ok": ok,
            "recomputed_name_match": recomputed,
            "live_fields": fields,
        })
    checks.append(_check(
        "decoy_accounts_prove_query_dead_by_foreign_id",
        bool(expected_decoys) and all(entry["ok"] for entry in matched),
        {
            "reason": "zero-match honesty: every seeded decoy Account's live read-back "
                      "carries a REAL RecordTypeId that is not the foreign literal, and "
                      "its declared LIKE-arm flag matches the recomputed containment -- "
                      "the empty result is attributable to the WHERE (foreign-ID "
                      "semantics), never to an empty org",
            "empty_reason": expect.get("empty_reason"),
            "expected_decoys": expected_decoys,
            "match_details": matched,
            "snapshot_account_names": sorted(accounts_by_name),
        },
    ))

    computed_reason = "foreign_record_type" if any_name_match else "no_name_match"
    checks.append(_check(
        "empty_reason_attributes_the_emptiness_honestly",
        expect.get("empty_reason") == computed_reason,
        {
            "reason": "'foreign_record_type' iff at least one decoy passes the LIKE arm "
                      "(the RT equality is then the SOLE excluder); 'no_name_match' iff "
                      "none does (emptiness overdetermined but the org is still proven "
                      "non-empty)",
            "expected_empty_reason": computed_reason,
            "declared_empty_reason": expect.get("empty_reason"),
        },
    ))

    cleanup_response = details.get("cleanup_response") or {}
    checks.append(_check(
        "live_salesforce_seed_records_cleaned_up",
        bool(cleanup_response.get("ok")) and not cleanup_response.get("leftovers"),
        {"cleanup_response": cleanup_response},
    ))

    return {"ok": _checks_ok(checks), "checks": checks}


def verify_122340768(result: dict[str, Any]) -> dict[str, Any]:
    return verify_125838852(result)


