    checks.append(_check(
        "menu_options_recomputed_from_live_rows",
        recomputed is not None and menu_options == recomputed,
        {
            "reason": "one {label: name, value: id} per live row, in row order "
                      "([] on zero matches)",
            "live_rows": sql_rows,
            "recomputed": recomputed,
            "actual_options": menu_options,
        },
    ))
    expected_options = expect.get("menu_options")
    ordered = expect.get("menu_options_ordered")
    if ordered:
        options_match = menu_options == expected_options
    else:
        def _option_key(option):
            if not isinstance(option, dict):
                return ("", "")
            return (str(option.get("label")), str(option.get("value")))

        options_match = (
            isinstance(menu_options, list)
            and isinstance(expected_options, list)
            and sorted(menu_options, key=_option_key) == sorted(expected_options, key=_option_key)
        )
    checks.append(_check(
        "menu_options_match_expected",
        options_match,
        {
            "reason": "multiset compare when menu_options_ordered is false (no ORDER "
                      "BY); exact compare for single/empty menus",
            "expected_options": expected_options,
            "ordered": ordered,
            "actual_options": menu_options,
        },
    ))
    checks.append(_check(
        "ordered_flag_coherent_with_option_count",
        (ordered is True and len(expected_options or []) <= 1)
        or (ordered is False and len(expected_options or []) > 1),
        {
            "reason": "the SELECT has no ORDER BY: multi-row menus must be pinned as a "
                      "multiset (ordered false); single/empty pin exact order",
            "ordered": ordered,
            "expected_options": expected_options,
        },
    ))
    checks.append(_check(
        "menu_values_are_int_ids_with_string_labels",
        isinstance(menu_options, list)
        and all(
            isinstance(option, dict)
            and sorted(option.keys()) == ["label", "value"]
            and isinstance(option.get("label"), str)
            and isinstance(option.get("value"), int)
            and not isinstance(option.get("value"), bool)
            for option in menu_options
        ),
        {
            "reason": "the value pill is a single-pill interpolation preserving the "
                      "INT type of the Snowflake NUMBER id (output_schema "
                      "integer_conversion), never a string",
            "actual_options": menu_options,
        },
    ))

    final_tables = ((details.get("final_snapshot") or {}).get("snowflake") or {}).get("tables")
    checks.append(_check(
        "snowflake_table_read_only",
        isinstance(initial_tables, dict)
        and sorted(initial_tables.keys()) == [TABLE_KEY]
        and initial_tables == final_tables,
        {
            "reason": "the recipe only READS the one seeded table; the live snapshots "
                      "must be identical before and after the run",
            "initial_tables": initial_tables,
            "final_tables": final_tables,
        },
    ))
    cleanup = details.get("cleanup_response") if isinstance(details.get("cleanup_response"), dict) else {}
    snowflake_cleanup = cleanup.get("snowflake_live") if isinstance(cleanup.get("snowflake_live"), dict) else {}
    checks.append(_check(
        "snowflake_cleanup_dropped_seeded_table",
        bool(snowflake_cleanup.get("ok"))
        and sorted(snowflake_cleanup.get("dropped_tables") or []) == [TABLE_KEY],
        {
            "reason": "the runner must drop the registered live table in its finally",
            "cleanup_response": cleanup,
        },
    ))

    stop_rows = [row for row in trace if isinstance(row, dict) and row.get("stopped") is True]
    checks.append(_check(
        "no_stop_occurred",
        not stop_rows,
        {"reason": "recipe 109200085 has no stop steps", "stop_rows": stop_rows},
    ))
    return {"ok": _checks_ok(checks), "checks": checks}


