def verify_97126841(result: dict[str, Any]) -> dict[str, Any]:
    import re as _re

    DECLARE_AS = "6658dcd5"
    POST_AS = "cfdec45a"
    RAW_CHANNEL = "#finance-close"
    BUTTON_TITLE = "Select Subsidiaries"
    EXPECTED_TRACE = ["workato_runtime.declare_variable", "slack.post_message"]
    MONTHS_ABBREV = (
        "Jan", "Feb", "Mar", "Apr", "May", "Jun",
        "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
    )
    base = _verify_replay_recipe(result)
    checks = list(base.get("checks") or [])
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") if isinstance(details.get("raw_execution"), dict) else {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    step_outputs = raw_execution.get("step_outputs") if isinstance(raw_execution.get("step_outputs"), dict) else {}
    tool_calls = result.get("tool_calls") if isinstance(result.get("tool_calls"), list) else []

    required = (
        "case", "executed_action_count", "tools", "trace_tools",
        "tool_expectations", "months_back", "run_month_slack_formatted", "post_text",
    )
    missing = [key for key in required if key not in expect]
    if missing:
        checks.append(_check(
            "expect_required_keys_missing",
            False,
            {
                "reason": "every 97126841 variant must pin the declare-strftime render "
                          "and the exact live post text",
                "missing_keys": missing,
                "expect": expect,
            },
        ))
        return {"ok": False, "checks": checks}

    # Independent re-derivation: (scheduled_time - 1.months).strftime('%b %Y')
    # on the seed's resolved trigger timestamp. The seeder anchors ticks to
    # day 1, so the decrement is a pure calendar-month step (no end-of-month
    # clamp ambiguity).
    trigger = details.get("trigger") if isinstance(details.get("trigger"), dict) else {}
    scheduled_time = str(trigger.get("scheduled_time") or "")
    match = _re.match(r"^(\d{4})-(\d{2})-01T10:00:00\+08:00$", scheduled_time)
    derived = None
    if match:
        year, month = int(match.group(1)), int(match.group(2))
        index = year * 12 + (month - 1) - 1
        derived = f"{MONTHS_ABBREV[index % 12]} {index // 12}"
    expected_text = f"*Run Allocation Schedule for {derived}*" if derived else None
    checks.append(_check(
        "seeded_tick_is_resolved_day1_instant",
        derived is not None,
        {
            "reason": "the stored trigger must carry the token-resolved monthly tick "
                      "(day-1 10:00:00+08:00, the pinned trigger config) — never a raw "
                      "$SCHEDULED_TICK token or an off-schedule instant",
            "scheduled_time": scheduled_time,
        },
    ))

    declared = step_outputs.get(DECLARE_AS)
    checks.append(_check(
        "declared_month_matches_scheduled_time_minus_one_month",
        derived is not None
        and declared == {"run_month_slack_formatted": derived}
        and expect.get("run_month_slack_formatted") == derived,
        {
            "reason": "the declare step formats the literal seeded scheduled_time minus "
                      "1.months with strftime('%b %Y') — month subtraction through the "
                      "arith duration engine, no timezone conversion",
            "expected": derived,
            "declared": declared,
            "expect_render": expect.get("run_month_slack_formatted"),
        },
    ))

    trace_tools = [
        row.get("tool")
        for row in trace
        if isinstance(row, dict) and row.get("keyword") == "action" and row.get("tool")
    ]
    checks.append(_check(
        "trace_action_sequence_matches",
        trace_tools == EXPECTED_TRACE and expect.get("trace_tools") == EXPECTED_TRACE,
        {"expected_trace": EXPECTED_TRACE, "actual_trace": trace_tools},
    ))

    post_calls = [call for call in tool_calls if call.get("tool") == "slack.post_message"]
    call = post_calls[0] if post_calls else {}
    args = call.get("args") or {}
    call_result = call.get("result") or {}
    post_rows = [row for row in trace if isinstance(row, dict) and row.get("tool") == "slack.post_message"]
    checks.append(_check(
        "single_live_post_exact_text_button_dropped",
        len(post_calls) == 1
        and len(tool_calls) == 1
        and len(post_rows) == 1
        and str(post_rows[0].get("as") or "") == POST_AS
        and expected_text is not None
        and args.get("text") == expected_text
        and expect.get("post_text") == expected_text
        and BUTTON_TITLE not in str(args.get("text") or "")
        and "blocks" not in args,
        {
            "reason": "exactly one live post whose text is the section_text ONLY — the "
                      "'Select Subsidiaries' bot_command button is dropped by slack_text "
                      "and no block payload reaches the live call",
            "expected_text": expected_text,
            "actual_args": args,
        },
    ))
    channel = str(args.get("channel") or "")
    checks.append(_check(
        "raw_channel_rerouted_to_override",
        bool(channel) and channel != RAW_CHANNEL and not channel.startswith("#"),
        {
            "reason": "'#finance-close' does not start with 'U' -> the adapter must "
                      "reroute the post to the env override channel; the raw literal "
                      "may never reach the live call",
            "raw_channel": RAW_CHANNEL,
            "actual_channel": channel,
        },
    ))
    checks.append(_check(
        "post_delivered_live",
        call_result.get("ok") is True and bool(str(call_result.get("ts") or "")),
        {"reason": "the live chat.postMessage response must be ok with a ts", "actual_result": call_result},
    ))
    stop_rows = [row for row in trace if isinstance(row, dict) and row.get("stopped") is True]
    checks.append(_check(
        "no_stop_occurred",
        not stop_rows,
        {"reason": "recipe 97126841 has no stop steps", "stop_rows": stop_rows},
    ))
    return {"ok": _checks_ok(checks), "checks": checks}


