def verify_108625382(result: dict[str, Any]) -> dict[str, Any]:
    SEARCH_AS = "826258bc"
    MENU_AS = "25629193"
    TABLE = "PUBLIC.EMPLOYEE"
    BRANCHES = (
        "email_arm_match",
        "name_arm_mixed_case",
        "email_case_quirk",
        "zero_match",
        "multi_match",
    )
    base = _verify_replay_recipe(result)
    checks = list(base.get("checks") or [])
    details = result.get("details") or {}
    expect = details.get("expect") if isinstance(details.get("expect"), dict) else {}
    raw_execution = details.get("raw_execution") or {}
    trace = raw_execution.get("trace") if isinstance(raw_execution.get("trace"), list) else []
    action_rows = [row for row in trace if isinstance(row, dict) and row.get("keyword") == "action"]
    trigger = details.get("trigger") if isinstance(details.get("trigger"), dict) else {}
    typeahead = str((trigger.get("typeahead") or {}).get("value") or "")

    required = ("branch", "menu_options", "executed_action_count", "tools", "tool_expectations")
    missing = [key for key in required if key not in expect]
    branch = str(expect.get("branch") or "")
    if missing or branch not in BRANCHES:
        checks.append(_check(
            "expect_required_keys_missing",
            False,
            {
                "reason": "every 108625382 variant must pin branch (one of "
                          f"{sorted(BRANCHES)}), menu_options and the strict tool "
                          "expectations",
                "missing_keys": missing,
                "branch": branch,
                "expect": expect,
            },
        ))
        return {"ok": False, "checks": checks}

    checks.append(_check(
        "trigger_is_bare_typeahead_and_sql_safe",
        set(trigger) == {"typeahead"} and typeahead != ""
        and "'" not in typeahead and "%" not in typeahead and "_" not in typeahead,
        {
            "reason": "the menu declares no parameters and the typeahead is "
                      "spliced raw into SQL twice: it must be quote- and "
                      "LIKE-wildcard-free so substring containment IS the LIKE "
                      "semantics this fragment re-computes",
            "trigger": trigger,
        },
    ))

    search_row = action_rows[0] if len(action_rows) == 2 else {}
    menu_row = action_rows[1] if len(action_rows) == 2 else {}
    checks.append(_check(
        "branchless_run_is_exactly_search_then_menu",
        len(action_rows) == 2
        and str(search_row.get("number")) == "2"
        and search_row.get("as") == SEARCH_AS
        and search_row.get("tool") == "snowflake.search_rows"
        and str(menu_row.get("number")) == "3"
        and menu_row.get("as") == MENU_AS
        and menu_row.get("tool") == "slack_bot.generate_menu_options",
        {
            "reason": "linear recipe: both steps run on every variant, in order",
            "action_rows": action_rows,
        },
    ))

    expected_where = (
        "EMAIL LIKE LOWER(CONCAT('%" + typeahead + "%'))\n"
        "OR LOWER(CONCAT(FIRST_NAME, ' ', LAST_NAME)) LIKE LOWER(CONCAT('%" + typeahead + "%'))"
    )
    expected_search_args = {
        "table": TABLE,
        "where": expected_where,
        "parameters": {},
        "limit": 50000,
        "offset": 0,
        "orderby": None,
        "output_columns": None,
    }
    checks.append(_check(
        "search_args_pinned_by_full_equality",
        (search_row.get("args") or {}) == expected_search_args,
        {
            "reason": "the where passthrough is re-derived verbatim from the "
                      "seeded typeahead (embedded newline included, typeahead "
                      "spliced twice); no binds, no projection, limit 50000 / "
                      "offset 0 as authored",
            "expected_args": expected_search_args,
            "actual_args": search_row.get("args"),
        },
    ))

    initial_snapshot = details.get("initial_snapshot") or {}
    final_snapshot = details.get("final_snapshot") or {}
    seeded_rows = (
        ((initial_snapshot.get("snowflake") or {}).get("tables") or {}).get(TABLE)
        if isinstance(initial_snapshot.get("snowflake"), dict) else None
    )
    seeded_rows = [row for row in (seeded_rows if isinstance(seeded_rows, list) else []) if isinstance(row, dict)]

    def _triple(row):
        return (
            str(row.get("email") or ""),
            str(row.get("first_name") or ""),
            str(row.get("last_name") or ""),
        )

    def _arm_email(row):
        # LOWER() lowers only the pattern: case-sensitive containment in the
        # STORED email (the recipe's faithful quirk).
        return typeahead.lower() in _triple(row)[0]

    def _arm_name(row):
        email, first, last = _triple(row)
        return typeahead.lower() in (first + " " + last).lower()

    checks.append(_check(
        "seeded_employee_table_present_and_nonempty",
        bool(seeded_rows),
        {
            "reason": "an empty seed cannot prove the where clause excluded "
                      "anything; the module refuses it at seed time too",
            "initial_snapshot": initial_snapshot,
        },
    ))

    predicted = [row for row in seeded_rows if _arm_email(row) or _arm_name(row)]
    live_rows = (search_row.get("result") or {}).get("rows")
    live_rows = [row for row in (live_rows if isinstance(live_rows, list) else []) if isinstance(row, dict)]
    checks.append(_check(
        "live_match_set_equals_recomputed_or_arm_semantics",
        sorted(_triple(row) for row in live_rows) == sorted(_triple(row) for row in predicted),
        {
            "reason": "the live Snowflake result must equal the Python "
                      "re-evaluation of the two OR arms over the seeded rows "
                      "(arm 1 case-sensitive on stored EMAIL, arm 2 both sides "
                      "lowered); compared order-free -- the query has no ORDER BY",
            "typeahead": typeahead,
            "predicted": [_triple(row) for row in predicted],
            "actual": [_triple(row) for row in live_rows],
            "seeded": [_triple(row) for row in seeded_rows],
        },
    ))

    derived_options = [
        {
            "label": "%s %s (%s)" % (_triple(row)[1], _triple(row)[2], _triple(row)[0]),
            "value": _triple(row)[0],
        }
        for row in live_rows
    ]
    checks.append(_check(
        "menu_options_re_derived_from_rows_and_pinned",
        (menu_row.get("args") or {}) == {"options": derived_options}
        and (menu_row.get("result") or {}) == {"ok": True, "options": derived_options},
        {
            "reason": "flat options path: args carry ONLY {options}; one "
                      "{label: 'first last (email)', value: email} option per row "
                      "in the order the menu consumed them (empty-list precedent: "
                      "the menu runs even with 0 rows)",
            "derived_options": derived_options,
            "actual_args": menu_row.get("args"),
            "actual_result": menu_row.get("result"),
        },
    ))

    menu_expect = expect.get("menu_options") if isinstance(expect.get("menu_options"), list) else []
    expected_pairs = sorted(
        (str((item or {}).get("label")), str((item or {}).get("value")))
        for item in menu_expect if isinstance(item, dict)
    )
    actual_pairs = sorted(
        (str(option.get("label")), str(option.get("value")))
        for option in derived_options
    )
    checks.append(_check(
        "menu_options_match_expected_set",
        actual_pairs == expected_pairs and len(derived_options) == len(menu_expect),
        {
            "reason": "expect.menu_options pinned as an exact (label, value) set "
                      "with exact count; order-free per the verify_57440133 "
                      "precedent on this same table",
            "expected_options": menu_expect,
            "actual_options": derived_options,
        },
    ))

    if branch == "email_arm_match":
        branch_ok = (
            len(live_rows) == 1
            and _arm_email(live_rows[0]) and not _arm_name(live_rows[0])
        )
        branch_reason = "the single admitted row must be admitted by arm 1 ONLY"
    elif branch == "name_arm_mixed_case":
        branch_ok = (
            len(live_rows) == 1
            and typeahead != typeahead.lower()
            and _arm_name(live_rows[0]) and not _arm_email(live_rows[0])
        )
        branch_reason = ("mixed-case typeahead admitted by the fully-lowered "
                         "full-name arm ONLY -- proves arm 2 lowers both sides")
    elif branch == "email_case_quirk":
        witnesses = [
            row for row in seeded_rows
            if typeahead.lower() in _triple(row)[0].lower()
            and typeahead.lower() not in _triple(row)[0]
        ]
        branch_ok = (
            live_rows == [] and derived_options == []
            and bool(witnesses)
            and not any(_arm_name(row) for row in seeded_rows)
        )
        branch_reason = ("a seeded row matches the email case-INsensitively but "
                         "not case-sensitively and no name matches: the [] menu "
                         "pins that arm 1 does NOT lower the EMAIL column "
                         "(faithful recipe quirk)")
    elif branch == "zero_match":
        branch_ok = live_rows == [] and derived_options == []
        branch_reason = ("neither arm admits any seeded row -> rows [] -> pinned "
                         "[] options")
    else:  # multi_match
        arm1_only = [row for row in live_rows if _arm_email(row) and not _arm_name(row)]
        arm2_only = [row for row in live_rows if _arm_name(row) and not _arm_email(row)]
        branch_ok = (
            len(live_rows) == 2
            and len(seeded_rows) >= 3
            and len(arm1_only) == 1 and len(arm2_only) == 1
        )
        branch_reason = ("2 of >= 3 seeded rows admitted via DIFFERENT arms "
                         "(one email-arm-only, one name-arm-only); the third row "
                         "proves real exclusion")
    checks.append(_check(
        "branch_arm_attribution_holds",
        branch_ok,
        {
            "reason": branch_reason,
            "branch": branch,
            "typeahead": typeahead,
            "live_rows": [_triple(row) for row in live_rows],
            "seeded": [_triple(row) for row in seeded_rows],
        },
    ))

    checks.append(_check(
        "snowflake_untouched_by_read_only_menu_recipe",
        bool(initial_snapshot) and initial_snapshot == final_snapshot,
        {"initial_snapshot": initial_snapshot, "final_snapshot": final_snapshot},
    ))

    return {"ok": _checks_ok(checks), "checks": checks}


def verify_108426411(result: dict[str, Any]) -> dict[str, Any]:
    return verify_108625382(result)
